public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    String[] input;

    switch (choice) {
        case 0:
            // Empty array
            input = new String[0];
            break;
        case 1:
            // Single element
            input = new String[]{"single"};
            break;
        case 2:
            // Two elements with same frequency
            input = new String[]{"a", "a", "b", "b"};
            break;
        case 3:
            // All elements same
            input = new String[]{"same", "same", "same", "same"};
            break;
        case 4:
            // Simple case with clear second most frequent
            input = new String[]{"aaa", "bbb", "ccc", "bbb", "aaa", "aaa"};
            break;
        case 5:
            // Multiple distinct with equal frequencies
            input = new String[]{"x", "y", "z", "x", "y", "z"};
            break;
        case 6:
            // Long array with random strings
            int len = random.nextInt(20) + 5;
            input = new String[len];
            for (int i = 0; i < len; i++) {
                input[i] = "str" + (random.nextInt(10));
            }
            break;
        case 7:
            // Array with null elements
            int len2 = random.nextInt(10) + 2;
            input = new String[len2];
            for (int i = 0; i < len2; i++) {
                if (random.nextBoolean()) {
                    input[i] = null;
                } else {
                    input[i] = "val" + (random.nextInt(5));
                }
            }
            break;
        case 8:
            // Array with empty strings
            input = new String[]{"", "", "", "a", "a", "b"};
            break;
        case 9:
            // Mixed case with all unique strings
            int len3 = random.nextInt(10) + 1;
            input = new String[len3];
            for (int i = 0; i < len3; i++) {
                input[i] = "unique" + i;
            }
            break;
        default:
            input = new String[]{"default"};
    }

    return new Object[]{input};
}

