            n = random.nextInt(10) + 1; // 1 to 10
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(200) - 100; // -100 to 99
            }
            break;
        case 1: // Empty array
            n = 0;
            arr = new int[0];
            break;
        case 2: // Single element
            n = 1;
            arr = new int[]{random.nextInt(200) - 100};
            break;
        case 3: // Strictly increasing
            n = random.nextInt(8) + 1;
            arr = new int[n];
            int start = random.nextInt(100) - 50;
            for (int i = 0; i < n; i++) {
                arr[i] = start + i * (random.nextInt(5) + 1);
            }
            break;
        case 4: // Strictly decreasing
            n = random.nextInt(8) + 1;
            arr = new int[n];
            start = random.nextInt(100) + 50;
            for (int i = 0; i < n; i++) {
                arr[i] = start - i * (random.nextInt(5) + 1);
            }
            break;
        default: // Boundary values
            n = random.nextInt(10) + 1;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                int boundaryChoice = random.nextInt(4);
                if (boundaryChoice == 0) arr[i] = Integer.MAX_VALUE;
                else if (boundaryChoice == 1) arr[i] = Integer.MIN_VALUE;
                else if (boundaryChoice == 2) arr[i] = 0;
                else arr[i] = random.nextInt(200) - 100;
            }
            break;
    }

    return new Object[]{arr, n};
}

