public static Object[] generateValidInput(Random random) {
    // Choose a scenario to generate diverse inputs
    int scenario = random.nextInt(11); // 0 to 10
    int[][] testArray;

    switch (scenario) {
        case 0: // null
            return new Object[]{null};
        case 1: // empty outer array
            testArray = new int[0][];
            return new Object[]{testArray};
        case 2: // single empty inner array
            testArray = new int[1][0];
            return new Object[]{testArray};
        case 3: // multiple empty inner arrays
            int rows = random.nextInt(3) + 2; // 2 to 4
            testArray = new int[rows][0];
            return new Object[]{testArray};
        case 4: // single row, single element
            int val = random.nextInt(200) - 100; // -100 to 99
            testArray = new int[][]{{val}};
            return new Object[]{testArray};
        case 5: // single row, multiple elements, some duplicates
            int len = random.nextInt(5) + 1; // 1 to 5
            int[] row = new int[len];
            // fill with some duplicates
            for (int i = 0; i < len; i++) {
                // with 50% chance duplicate a previous element
                if (i > 0 && random.nextBoolean()) {
                    row[i] = row[random.nextInt(i)];
                } else {
                    row[i] = random.nextInt(200) - 100;
                }
            }
            testArray = new int[][]{row};
            return new Object[]{testArray};
        case 6: // multiple rows, all unique values
            int rows6 = random.nextInt(3) + 1; // 1 to 3
            int[][] temp6 = new int[rows6][];
            Set<Integer> used = new HashSet<>();
            for (int r = 0; r < rows6; r++) {
                int cols = random.nextInt(3) + 1; // 1 to 3
                int[] row6 = new int[cols];
                for (int c = 0; c < cols; c++) {
                    int val6;
                    do {
                        val6 = random.nextInt(200) - 100;
                    } while (used.contains(val6));
                    used.add(val6);
                    row6[c] = val6;
                }
                temp6[r] = row6;
            }
            return new Object[]{temp6};
        case 7: // multiple rows, with duplicates across rows
            int rows7 = random.nextInt(3) + 2; // 2 to 4
            int[][] temp7 = new int[rows7][];
            // generate a pool of values, some will be repeated
            int poolSize = random.nextInt(5) + 2; // 2 to 6
            int[] pool = new int[poolSize];
            for (int i = 0; i < poolSize; i++) {
                pool[i] = random.nextInt(200) - 100;
            }
            for (int r = 0; r < rows7; r++) {
                int cols = random.nextInt(3) + 1; // 1 to 3
                int[] row7 = new int[cols];
                for (int c = 0; c < cols; c++) {
                    // pick from pool with high probability
                    if (random.nextDouble() < 0.7) {
                        row7[c] = pool[random.nextInt(poolSize)];
                    } else {
                        row7[c] = random.nextInt(200) - 100;
                    }
                }
                temp7[r] = row7;
            }
            return new Object[]{temp7};
        case 8: // include Integer.MIN_VALUE and MAX_VALUE
            testArray = new int[][]{
                {Integer.MIN_VALUE, 0, Integer.MAX_VALUE},
                {random.nextInt()}
            };
            return new Object[]{testArray};
        case 9: // include negative numbers and zero
            testArray = new int[][]{
                {-1, -2, -3},
                {0, -5, -10},
                {random.nextInt(10) - 5}
            };
            return new Object[]{testArray};
        case 10: // fully random mix
            int rows10 = random.nextInt(5) + 1; // 1 to 5
            int[][] temp10 = new int[rows10][];
            for (int r = 0; r < rows10; r++) {
                int cols = random.nextInt(5); // 0 to 4
                int[] row10 = new int[cols];
                for (int c = 0; c < cols; c++) {
                    row10[c] = random.nextInt();
                }
                temp10[r] = row10;
            }
            return new Object[]{temp10};
        default:
            // fallback: empty array
            return new Object[]{new int[0][]};
    }
}

