public static Object[] generateValidInput(Random random) {
    // Choose array length: 0, 1, 2, or random up to 5
    int n;
    int arrayLen;
    int type = random.nextInt(5);
    if (type == 0) {
        n = 0;
        arrayLen = 0;
    } else if (type == 1) {
        n = 1;
        arrayLen = 1;
    } else if (type == 2) {
        n = 2;
        arrayLen = 2;
    } else if (type == 3) {
        n = random.nextInt(5) + 1;
        arrayLen = n;
    } else {
        // n larger than array length to test index out of bounds robustness
        n = random.nextInt(5) + 3;
        arrayLen = random.nextInt(n) + 1;
    }

    String[] arr = new String[arrayLen];

    // Generate strings with possible common prefixes
    if (arrayLen > 0) {
        // Base string to derive others from
        int baseLen = random.nextInt(6); // 0-5
        StringBuilder base = new StringBuilder();
        String alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
        for (int i = 0; i < baseLen; i++) {
            base.append(alphabet.charAt(random.nextInt(alphabet.length())));
        }
        String baseStr = base.toString();

        for (int i = 0; i < arrayLen; i++) {
            int choice = random.nextInt(4);
            if (choice == 0) {
                // Exact same as base
                arr[i] = baseStr;
            } else if (choice == 1) {
                // Prefix of base plus random suffix
                int prefixLen = random.nextInt(baseLen + 1);
                String prefix = baseStr.substring(0, prefixLen);
                int suffixLen = random.nextInt(5);
                StringBuilder sb = new StringBuilder(prefix);
                for (int j = 0; j < suffixLen; j++) {
                    sb.append(alphabet.charAt(random.nextInt(alphabet.length())));
                }
                arr[i] = sb.toString();
            } else if (choice == 2) {
                // Completely different string
                int len = random.nextInt(6);
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < len; j++) {
                    sb.append(alphabet.charAt(random.nextInt(alphabet.length())));
                }
                arr[i] = sb.toString();
            } else {
                // Empty string
                arr[i] = "";
            }
        }
    }

    return new Object[]{arr, n};
}

