    int x, y, m, n;
    int choice = random.nextInt(6);
    switch (choice) {
        case 0: // Normal case: sum inside range
            x = random.nextInt(100);
            y = random.nextInt(100);
            int sum = x + y;
            m = sum - random.nextInt(10);
            n = sum + random.nextInt(10);
            break;
        case 1: // Sum outside range (less than m)
            x = random.nextInt(100);
            y = random.nextInt(100);
            sum = x + y;
            m = sum + 1 + random.nextInt(10);
            n = m + random.nextInt(10);
            break;
        case 2: // Sum outside range (greater than n)
            x = random.nextInt(100);
            y = random.nextInt(100);
            sum = x + y;
            n = sum - 1 - random.nextInt(10);
            m = n - random.nextInt(10);
            break;
        case 3: // Boundary: sum equals m or n
            if (random.nextBoolean()) {
                x = random.nextInt(50);
                y = random.nextInt(50);
                sum = x + y;
                m = sum;
                n = sum + random.nextInt(10);
            } else {
                x = random.nextInt(50);
                y = random.nextInt(50);
                sum = x + y;
                n = sum;
                m = sum - random.nextInt(10);
            }
            break;
        case 4: // Edge cases: overflow, extreme values
            if (random.nextBoolean()) {
                x = Integer.MAX_VALUE;
                y = 1; // overflow
                m = Integer.MIN_VALUE;
                n = Integer.MAX_VALUE;
            } else {
                x = Integer.MIN_VALUE;
                y = -1; // underflow
                m = Integer.MIN_VALUE;
                n = Integer.MAX_VALUE;
            }
            break;
        case 5: // Reversed range (m > n), or negative values
            if (random.nextBoolean()) {
                // reversed range: sum cannot be inside
                m = 50;
                n = 20;
                x = random.nextInt(100);
                y = random.nextInt(100);
            } else {
                // negative numbers
                x = -random.nextInt(100);
                y = -random.nextInt(100);
                sum = x + y;
                m = sum - 10;
                n = sum + 10;
            }
            break;
        default:
            x = 0; y = 0; m = -1; n = 1; // sum=0 inside [-1,1]
    }
    return new Object[]{x, y, m, n};
}

