            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt(21) - 10;
            }
            break;
        default:
            // Array with duplicates and consecutive values
            int len2 = random.nextInt(6) + 2;
            arr = new int[len2];
            int current = random.nextInt(10);
            for (int i = 0; i < len2; i++) {
                arr[i] = current;
                if (random.nextBoolean()) {
                    current++;
                }
            }
            break;
    }
    return new Object[]{arr};
}

