            }
        }
    } else if (choice < 6) {
        // Boundary values: Integer.MAX_VALUE, Integer.MIN_VALUE, 0, 1, -1
        int rows = random.nextInt(3) + 1; // 1 to 3
        int cols = random.nextInt(3) + 1; // 1 to 3
        testTup1 = new int[rows][cols];
        testTup2 = new int[rows][cols];
        // Fill with random boundary values
        int[] boundaryValues = {Integer.MAX_VALUE, Integer.MIN_VALUE, 0, 1, -1};
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                testTup1[i][j] = boundaryValues[random.nextInt(boundaryValues.length)];
                testTup2[i][j] = boundaryValues[random.nextInt(boundaryValues.length)];
            }
        }
