public static Object[] generateValidInput(Random random) {
    // Decide type of input
    int choice = random.nextInt(10);
    int[] nums;

    switch (choice) {
        case 0: // null
            nums = null;
            break;
        case 1: // empty array
            nums = new int[0];
            break;
        case 2: // single element
            nums = new int[]{random.nextBoolean() ? 0 : random.nextInt(200) - 100};
            break;
        case 3: // two elements, same
            nums = new int[]{random.nextInt(200) - 100, random.nextInt(200) - 100};
            break;
        case 4: // two elements, different
            nums = new int[]{random.nextInt(200) - 100, random.nextInt(200) - 100 + 1};
            break;
        case 5: // three elements, all different
            nums = new int[]{random.nextInt(200) - 100, random.nextInt(200) - 100, random.nextInt(200) - 100};
            break;
        case 6: // three elements, exactly one duplicate (two same, one different)
            int val = random.nextInt(200) - 100;
            nums = new int[]{val, val, random.nextInt(200) - 100};
            break;
        case 7: // boundary values: Integer.MIN_VALUE, MAX_VALUE, 0, -1, 1
            int[] boundaries = {Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1};
            int len = random.nextInt(5) + 1; // 1..5
            nums = new int[len];
            for (int i = 0; i < len; i++) {
                nums[i] = boundaries[random.nextInt(boundaries.length)];
            }
            break;
        case 8: // random array with duplicates (some appear twice, some once, some three times)
            int size = random.nextInt(10) + 2; // 2..11
            nums = new int[size];
            for (int i = 0; i < size; i++) {
                // With some probability, repeat a previous value
                if (i > 0 && random.nextDouble() < 0.3) {
                    nums[i] = nums[random.nextInt(i)];
                } else {
                    nums[i] = random.nextInt(100) - 50;
                }
            }
            break;
        default: // random array, no specific pattern
            int len2 = random.nextInt(15) + 1; // 1..15
            nums = new int[len2];
            for (int i = 0; i < len2; i++) {
                nums[i] = random.nextInt(200) - 100;
            }
            break;
    }

    return new Object[]{nums};
}

