public static Object[] generateValidInput(Random random) {
    // Decide on the type of input scenario
    int scenario = random.nextInt(10);
    int[] a;
    int n;
    int k;

    // Helper to generate a random integer with boundary values
    java.util.function.IntSupplier randomInt = () -> {
        int r = random.nextInt(10);
        if (r < 2) {
            // boundary values
            int[] boundaries = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
            return boundaries[random.nextInt(boundaries.length)];
        } else {
            // random value in range [-100, 100]
            return random.nextInt(201) - 100;
        }
    };

    // Helper to generate an array of given length
    java.util.function.IntFunction<int[]> arrayGen = (len) -> {
        int[] arr = new int[len];
        for (int i = 0; i < len; i++) {
            arr[i] = randomInt.getAsInt();
        }
        return arr;
    };

    switch (scenario) {
        case 0: // null array
            a = null;
            n = random.nextInt(10);  // any n
            k = random.nextInt(10);
            break;
        case 1: // empty array
            a = new int[0];
            n = 0;
            k = random.nextInt(5) - 2; // negative, zero, positive
            break;
        case 2: // single element array
            a = new int[]{randomInt.getAsInt()};
            n = 1;
            k = random.nextInt(3); // 0,1,2
            break;
        case 3: // all positive, length variable
            int len = random.nextInt(5) + 1;
            a = new int[len];
            for (int i = 0; i < len; i++) {
                a[i] = random.nextInt(100) + 1; // positive
            }
            n = len;
            k = random.nextInt(n + 2); // 0..n+1
            break;
        case 4: // all negative
            len = random.nextInt(5) + 1;
            a = new int[len];
            for (int i = 0; i < len; i++) {
                a[i] = -(random.nextInt(100) + 1); // negative
            }
            n = len;
            k = random.nextInt(n + 2);
            break;
        case 5: // mixed, n = length, k = n (equal)
            len = random.nextInt(5) + 2;
            a = arrayGen.apply(len);
            n = len;
            k = n;
            break;
        case 6: // mixed, n = length, k > n
            len = random.nextInt(5) + 2;
            a = arrayGen.apply(len);
            n = len;
            k = n + random.nextInt(3) + 1; // > n
            break;
        case 7: // mixed, n = length, k = 0
            len = random.nextInt(5) + 1;
            a = arrayGen.apply(len);
            n = len;
            k = 0;
            break;
        case 8: // n = 0, array non-empty
            len = random.nextInt(5) + 1;
            a = arrayGen.apply(len);
            n = 0;
            k = random.nextInt(5);
            break;
        case 9: // n negative, array non-empty
            len = random.nextInt(5) + 1;
            a = arrayGen.apply(len);
            n = -(random.nextInt(5) + 1); // negative
            k = random.nextInt(5) - 2; // negative, zero, positive
            break;
        default:
            // fallback: normal case
            len = random.nextInt(6) + 2;
            a = arrayGen.apply(len);
            n = len;
            k = random.nextInt(n + 2);
            break;
    }

    return new Object[]{a, n, k};
}

