public static Object[] generateValidInput(Random random) {
    int arrayLength = random.nextInt(12); // 0 to 11
    int[] array = new int[arrayLength];
    for (int i = 0; i < arrayLength; i++) {
        array[i] = random.nextInt(21) - 10; // -10 to 10
    }

    // Generate m and n based on array length
    int m, n;
    if (arrayLength == 0) {
        // For empty array, m and n can be anything, but typical edge cases
        m = random.nextInt(3); // 0, 1, 2
        n = random.nextInt(3); // 0, 1, 2
    } else {
        // Random valid range for m (0 to arrayLength-1) and n (0 to arrayLength)
        m = random.nextInt(arrayLength); // 0 to arrayLength-1
        n = random.nextInt(arrayLength + 1); // 0 to arrayLength
    }

    // Occasionally use boundary values
    if (random.nextBoolean()) {
        m = 0;
    } else if (random.nextBoolean()) {
        m = arrayLength > 0 ? arrayLength - 1 : 0;
    }

    if (random.nextBoolean()) {
        n = 0;
    } else if (random.nextBoolean()) {
        n = arrayLength;
    }

    // Edge case: n > m can cause index out of bounds in the second loop, but that's a potential bug in the method
    // We'll include some cases with n > m to test robustness
    if (random.nextInt(10) < 3 && arrayLength > 0) {
        n = random.nextInt(arrayLength * 2 + 1); // could exceed arrayLength
    }

    return new Object[]{array, m, n};
}

