                firstNested[i] = random.nextInt(100) - 50;
            }
            input = firstNested;
            break;
        case 3:
            // Array with nested array somewhere in the middle
            int pos = random.nextInt(10) + 1;
            Object[] middleNested = new Object[pos + 1];
            for (int i = 0; i < pos; i++) {
                middleNested[i] = random.nextInt(100) - 50;
            }
            middleNested[pos] = new Object[]{random.nextInt(10)};
            input = middleNested;
            break;
        case 4:
            // Array with deeply nested array as first element
            input = new Object[]{new Object[]{new Object[]{random.nextInt(10)}}};
