    // Randomly choose length of string
    int length;
    // Bias towards boundary values: 0, 1, and a few longer
    int choice = random.nextInt(10);
    if (choice < 2) {
        length = 0;                         // empty string
    } else if (choice < 5) {
        length = 1;                         // single character
    } else {
        length = 2 + random.nextInt(9);     // 2 to 10 characters
    }

    StringBuilder sb = new StringBuilder();
    if (length == 0) {
        // No characters
    } else if (length == 1) {
        // Any single character (including non-letter)
        char c = (char) (random.nextInt(95) + 32); // printable ASCII range 32-126
        sb.append(c);
    } else {
        // length >= 2
        // Decide whether to generate a valid or invalid case
        boolean valid = random.nextBoolean();

        // Generate first character
        char firstChar;
        if (valid) {
            // Must be a letter (a-z, A-Z)
            firstChar = (char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26));
        } else {
            // Randomly choose a non-letter, or a letter but with mismatched last char
            if (random.nextDouble() < 0.3) {
                // Non-letter first character
                firstChar = (char) (random.nextInt(15) + 33); // ! to /, digits, etc.
            } else {
                // Letter first character, but last character will be different
                firstChar = (char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26));
            }
        }
        sb.append(firstChar);

        // Generate middle part (random characters, may be empty)
        int middleLen = length - 2;
        for (int i = 0; i < middleLen; i++) {
            char midChar = (char) (random.nextInt(95) + 32); // printable ASCII
            sb.append(midChar);
        }

        // Generate last character
        char lastChar;
        if (valid) {
            lastChar = firstChar; // same character
        } else {
            // Different character: either different letter, non-letter, or same letter different case
            int choiceLast = random.nextInt(3);
            if (choiceLast == 0) {
                // Different letter (same case or different case)
                do {
                    lastChar = (char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26));
                } while (lastChar == firstChar);
            } else if (choiceLast == 1) {
                // Non-letter (e.g., digit, punctuation)
                lastChar = (char) (random.nextInt(15) + 33); // ! to /, digits, etc.
            } else {
                // Same letter but different case (if firstChar is a letter)
                if (Character.isLetter(firstChar)) {
                    lastChar = Character.isUpperCase(firstChar) ? Character.toLowerCase(firstChar) : Character.toUpperCase(firstChar);
                } else {
                    // firstChar not a letter, just use a random non-letter
                    lastChar = (char) (random.nextInt(15) + 33);
                }
            }
        }
        sb.append(lastChar);
    }

    String input = sb.toString();
    return new Object[] { input };
}

