public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(7);
    int[] array;

    switch (choice) {
        case 0:
            // Empty array
            array = new int[0];
            break;
        case 1:
            // Single element - even
            array = new int[]{2};
            break;
        case 2:
            // Single element - odd
            array = new int[]{1};
            break;
        case 3:
            // Boundary values
            array = new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE, 0, 1, -1};
            break;
        case 4:
            // All even numbers including zero
            array = new int[]{0, 2, 4, 6, 8, -2, -4, Integer.MIN_VALUE};
            break;
        case 5:
            // All odd numbers
            array = new int[]{1, 3, 5, 7, 9, -1, -3, Integer.MAX_VALUE};
            break;
        default:
            // Random mixed array
            int length = random.nextInt(15) + 1; // 1 to 15 elements
            array = new int[length];
            for (int i = 0; i < length; i++) {
                array[i] = random.nextInt(2001) - 1000; // -1000 to 1000
            }
            break;
    }

    return new Object[]{array};
}

