public static Object[] generateValidInput(Random random) {
    // Generate a random string length between 0 and 20
    int len = random.nextInt(21);
    StringBuilder sb = new StringBuilder();

    // Randomly decide pattern type
    int patternType = random.nextInt(4);

    if (patternType == 0) {
        // All same characters (e.g., "aaaa")
        if (len == 0) {
            // empty string
        } else {
            char c = (char) ('0' + random.nextInt(10));
            for (int i = 0; i < len; i++) {
                sb.append(c);
            }
        }
    } else if (patternType == 1) {
        // Alternating two different characters (e.g., "abab")
        if (len == 0) {
            // empty string
        } else {
            char c1 = (char) ('a' + random.nextInt(26));
            char c2;
            do {
                c2 = (char) ('a' + random.nextInt(26));
            } while (c1 == c2);
            for (int i = 0; i < len; i++) {
                sb.append(i % 2 == 0 ? c1 : c2);
            }
        }
    } else if (patternType == 2) {
        // Random string with mixed characters
        for (int i = 0; i < len; i++) {
            sb.append((char) ('a' + random.nextInt(26)));
        }
    } else {
        // Edge cases: odd length (always returns true), length 1, length 2, etc.
        switch (random.nextInt(5)) {
            case 0:
                // odd length, alternating pattern
                if (len == 0) {
                    sb.append("a");
                } else {
                    len = len * 2 + 1; // ensure odd
                    char c1 = (char) ('0' + random.nextInt(10));
                    char c2;
                    do {
                        c2 = (char) ('0' + random.nextInt(10));
                    } while (c1 == c2);
                    for (int i = 0; i < len; i++) {
                        sb.append(i % 2 == 0 ? c1 : c2);
                    }
                }
                break;
            case 1:
                // exactly "1212121"
                sb.append("1212121");
                break;
            case 2:
                // exactly "1991"
                sb.append("1991");
                break;
            case 3:
                // exactly "121"
                sb.append("121");
                break;
            case 4:
                // exactly "11" (even, all same -> returns true)
                sb.append("11");
                break;
        }
    }

    return new Object[]{sb.toString()};
}

