        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            int choice = random.nextInt(3);
            if (choice == 0) arr[i] = Integer.MIN_VALUE;
            else if (choice == 1) arr[i] = Integer.MAX_VALUE;
            else arr[i] = random.nextInt(21) - 10;
        }
        return new Object[]{arr, n};
    } else if (caseType == 3) {
        // Array with consecutive numbers (increasing or decreasing)
        int n = 1 + random.nextInt(10);
        int[] arr = new int[n];
        int start = random.nextInt(21) - 10;
        boolean increasing = random.nextBoolean();
        for (int i = 0; i < n; i++) {
            arr[i] = increasing ? start + i : start - i;
        }
        return new Object[]{arr, n};
    } else {
        // Random array with varied values, including duplicates and consecutive differences
        int n = 1 + random.nextInt(15);
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = random.nextInt(21) - 10;
        }
        return new Object[]{arr, n};
    }
}

