public static Object[] generateValidInput(Random random) {
    int size;
    int type = random.nextInt(5);
    switch (type) {
        case 0: // empty array
            size = 0;
            break;
        case 1: // single element
            size = 1;
            break;
        case 2: // small array
            size = random.nextInt(5) + 2; // 2-6
            break;
        case 3: // medium array
            size = random.nextInt(10) + 5; // 5-14
            break;
        default: // large array
            size = random.nextInt(20) + 10; // 10-29
            break;
    }

    int[] arr = new int[size];
    int rangeType = random.nextInt(4);
    int minVal, maxVal;
    switch (rangeType) {
        case 0: // small range values
            minVal = 0;
            maxVal = 3;
            break;
        case 1: // negative values
            minVal = -5;
            maxVal = 5;
            break;
        case 2: // full int range
            minVal = Integer.MIN_VALUE;
            maxVal = Integer.MAX_VALUE;
            break;
        default: // moderate range
            minVal = -10;
            maxVal = 10;
            break;
    }

    for (int i = 0; i < size; i++) {
        if (minVal == Integer.MIN_VALUE && maxVal == Integer.MAX_VALUE) {
            arr[i] = random.nextInt();
        } else {
            arr[i] = random.nextInt(maxVal - minVal + 1) + minVal;
        }
    }

    // Include boundary values sometimes
    if (size > 0 && random.nextBoolean()) {
        arr[random.nextInt(size)] = Integer.MIN_VALUE;
    }
    if (size > 0 && random.nextBoolean()) {
        arr[random.nextInt(size)] = Integer.MAX_VALUE;
    }
    if (size > 0 && random.nextBoolean()) {
        arr[random.nextInt(size)] = 0;
    }
    if (size > 0 && random.nextBoolean()) {
        arr[random.nextInt(size)] = 1;
    }
    if (size > 0 && random.nextBoolean()) {
        arr[random.nextInt(size)] = -1;
    }

    // Ensure some duplicates in some cases
    if (size > 2 && random.nextBoolean()) {
        int dupIndex1 = random.nextInt(size);
        int dupIndex2 = random.nextInt(size);
        arr[dupIndex2] = arr[dupIndex1];
    }

    return new Object[]{arr};
}

