            for(int i = 0; i < len; i++) sb.append(c);
            str = sb.toString();
            break;
        case 3:
            // Random string with varied characters
            int length = random.nextInt(30) + 1;
            sb = new StringBuilder();
            for(int i = 0; i < length; i++) {
                sb.append((char)('a' + random.nextInt(26)));
            }
            str = sb.toString();
            break;
        default:
            // String with all 26 letters
            sb = new StringBuilder();
            for(int i = 0; i < 26; i++) {
                sb.append((char)('a' + i));
            }
            str = sb.toString();
            break;
    }

    return new Object[]{str};
}

