public static Object[] generateValidInput(Random random) {
    // Decide whether to include null arrays (about 10% chance each)
    boolean null1 = random.nextDouble() < 0.1;
    boolean null2 = random.nextDouble() < 0.1;
    boolean null3 = random.nextDouble() < 0.1;

    int[] arr1 = null1 ? null : generateArray(random, true);
    int[] arr2 = null2 ? null : generateArray(random, true);
    int[] arr3 = null3 ? null : generateArray(random, true);

    // Occasionally make all three arrays identical (non-null) to produce many matches
    if (random.nextDouble() < 0.2 && arr1 != null && arr2 != null && arr3 != null) {
        int len = Math.min(arr1.length, Math.min(arr2.length, arr3.length));
        for (int i = 0; i < len; i++) {
            int val = random.nextInt(200) - 100; // random value
            arr1[i] = val;
            arr2[i] = val;
            arr3[i] = val;
        }
    }

    // Occasionally insert boundary values into the first few positions (if arrays are non-null)
    if (arr1 != null && arr1.length > 0) {
        arr1[0] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
    }
    if (arr2 != null && arr2.length > 0) {
        arr2[0] = random.nextBoolean() ? -1 : 0;
    }
    if (arr3 != null && arr3.length > 0) {
        arr3[0] = random.nextBoolean() ? 1 : 0;
    }

    return new Object[]{arr1, arr2, arr3};
}

// Helper to generate a random int array (possibly empty)
private static int[] generateArray(Random random, boolean allowEmpty) {
    int length;
    if (allowEmpty && random.nextDouble() < 0.15) {
        length = 0;
    } else {
        length = random.nextInt(10) + 1; // 1..10
    }
    int[] arr = new int[length];
    for (int i = 0; i < length; i++) {
        // Mix of random values and boundaries
        int choice = random.nextInt(10);
        if (choice < 6) {
            arr[i] = random.nextInt(200) - 100; // -100..99
        } else if (choice < 8) {
            arr[i] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        } else {
            arr[i] = random.nextBoolean() ? -1 : 1;
        }
    }
    return arr;
}

