public static Object[] generateValidInput(Random random) {
    // Determine length of the array (0 to 14)
    int length = random.nextInt(15);
    int[][] testArray = new int[length][2];

    // Special values to cover boundaries
    int[] specials = {
        Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1, 100, -100
    };

    for (int i = 0; i < length; i++) {
        int a, b;
        // Decide whether to use special values or fully random
        if (random.nextBoolean()) {
            // Use special values
            a = specials[random.nextInt(specials.length)];
            b = specials[random.nextInt(specials.length)];
        } else {
            // Fully random ints
            a = random.nextInt();
            b = random.nextInt();
        }
        testArray[i][0] = a;
        testArray[i][1] = b;
    }

    // Occasionally include a case with overflow causing Math.abs(Integer.MIN_VALUE)
    // This can be done by ensuring a pair has difference exactly Integer.MIN_VALUE
    if (length > 0 && random.nextBoolean()) {
        int idx = random.nextInt(length);
        // Set a = Integer.MAX_VALUE, b = -1 -> difference = Integer.MIN_VALUE (overflow)
        // But if we always set the same pair, we reduce randomness. Instead, conditionally set.
        if (random.nextBoolean()) {
            testArray[idx][0] = Integer.MAX_VALUE;
            testArray[idx][1] = -1;
        } else {
            testArray[idx][0] = Integer.MIN_VALUE;
            testArray[idx][1] = 1; // difference = Integer.MIN_VALUE - 1? Actually Integer.MIN_VALUE - 1 = Integer.MAX_VALUE? Let's use classic: a = Integer.MIN_VALUE, b = 1 -> difference = Integer.MIN_VALUE - 1 = Integer.MAX_VALUE? No, Math.abs(Integer.MIN_VALUE - 1) = Math.abs(Integer.MAX_VALUE) = Integer.MAX_VALUE, not overflow. Better to use a = Integer.MAX_VALUE, b = -1 gives difference = Integer.MIN_VALUE. So we'll do that.
        }
    }

    // Ensure diversity: sometimes make all pairs equal (maxDiff stays 0)
    if (length > 1 && random.nextDouble() < 0.1) {
        int val = random.nextInt();
        for (int i = 0; i < length; i++) {
            testArray[i][0] = val;
            testArray[i][1] = val;
        }
    }

    return new Object[]{testArray};
}

