import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {

    //@ requires cost != null;
    //@ requires n > 0;
    //@ requires cost.length >= n;
    //@ requires (\forall int i; 0 <= i && i < n; cost[i] != null && cost[i].length >= n);
    //@ ensures \result != null;
    //@ ensures !\result.isNaN();
    //@ ensures n == 1 ==> \result == (double)cost[0][0];
    //@ ensures (\forall int r; 0 <= r && r < n; (\forall int c; 0 <= c && c < n; cost[r][c] >= 0)) ==> \result >= (double)cost[0][0] / (2 * n - 1);
    public static Double maxaverageofpath(int[][] cost, int n) {
        double[][] dp = new double[n][n];

        dp[0][0] = cost[0][0];

        //@ loop_invariant 1 <= i && i <= n;
        //@ loop_invariant (\forall int k; 0 <= k < i; dp[k][0] == (\sum int m; 0 <= m && m <= k; (double)cost[m][0]));
        //@ loop_decreases n - i;
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost[i][0];
        }

        //@ loop_invariant 1 <= j && j <= n;
        //@ loop_invariant (\forall int k; 0 <= k < j; dp[0][k] == (\sum int m; 0 <= m && m <= k; (double)cost[0][m]));
        //@ loop_decreases n - j;
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost[0][j];
        }

        //@ loop_invariant 1 <= i && i <= n;
        //@ loop_decreases n - i;
        for (int i = 1; i < n; i++) {
            //@ loop_invariant 1 <= j && j <= n;
            //@ loop_decreases n - j;
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
            }
        }

        return dp[n - 1][n - 1] / (2 * n - 1);
    }
}

