public static Object[] generateValidInput(Random random) {
    int caseType = random.nextInt(8);
    String[] arr;
    switch (caseType) {
        case 0:
            // Empty array
            arr = new String[0];
            break;
        case 1:
            // Single element
            arr = new String[]{"abc"};
            break;
        case 2:
            // All duplicates
            arr = new String[]{"x", "x", "x"};
            break;
        case 3:
            // Mixed with duplicates
            arr = new String[]{"a", "b", "a", "c", "b", "d"};
            break;
        case 4:
            // Null array
            arr = null;
            break;
        case 5:
            // Array with null elements
            arr = new String[]{"a", null, "b", null, "a"};
            break;
        case 6:
            // Large random array with possible duplicates
            int size = random.nextInt(20) + 1;
            arr = new String[size];
            String[] words = {"apple", "banana", "cherry", "date", "elderberry"};
            for (int i = 0; i < size; i++) {
                arr[i] = words[random.nextInt(words.length)];
            }
            break;
        default:
            // Random length array with random strings
            int len = random.nextInt(15);
            arr = new String[len];
            for (int i = 0; i < len; i++) {
                int strLen = random.nextInt(6) + 1;
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < strLen; j++) {
                    sb.append((char) ('a' + random.nextInt(26)));
                }
                arr[i] = sb.toString();
            }
            break;
    }
    return new Object[]{arr};
}

