    int[] testTup;
    // 10% chance of null array
    if (random.nextDouble() < 0.1) {
        testTup = null;
    } else {
        // choose array length with bias for edge cases
        int len;
        double lenChoice = random.nextDouble();
        if (lenChoice < 0.2) {
            len = 0; // empty array
        } else if (lenChoice < 0.4) {
            len = 1; // single element
        } else {
            len = random.nextInt(5) + 2; // length 2..6
        }
        testTup = new int[len];
        for (int i = 0; i < len; i++) {
            // 10% chance of extreme values
            if (random.nextDouble() < 0.1) {
                testTup[i] = random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE;
            } else {
                testTup[i] = random.nextInt(201) - 100; // -100 to 100
            }
        }
    }

    // choose n covering boundary values
    int n;
    double nChoice = random.nextDouble();
    if (nChoice < 0.2) {
        n = -1; // negative (will cause exception)
    } else if (nChoice < 0.4) {
        n = 0; // zero repetitions
    } else if (nChoice < 0.6) {
        n = 1; // single repetition
    } else if (nChoice < 0.8) {
        n = random.nextInt(5) + 2; // 2..6
    } else {
        n = random.nextInt(10) + 7; // 7..16, larger but still manageable
    }

    return new Object[]{testTup, n};
}

