public static Object[] generateValidInput(Random random) {
    HashMap<String, Integer> dict = new HashMap<String, Integer>();
    int scenario = random.nextInt(6);
    if (scenario == 0) {
        // empty map
    } else if (scenario == 1) {
        dict.put("Cierra Vega", 175);
        dict.put("Alden Cantrell", 180);
        dict.put("Kierra Gentry", 165);
        dict.put("Pierre Cox", 190);
    } else if (scenario == 2) {
        // random map with mixed values
        int size = random.nextInt(8) + 1;
        for (int i = 0; i < size; i++) {
            dict.put("Key" + i, random.nextInt(401) - 200);
        }
    } else if (scenario == 3) {
        // boundary values
        dict.put("Max", Integer.MAX_VALUE);
        dict.put("Min", Integer.MIN_VALUE);
        dict.put("Zero", 0);
        dict.put("NegOne", -1);
        dict.put("One", 1);
    } else if (scenario == 4) {
        // all values equal to a common threshold
        int v = random.nextInt(201) - 100;
        dict.put("A", v);
        dict.put("B", v);
        dict.put("C", v);
    } else {
        // single entry
        dict.put("Only", random.nextInt(201) - 100);
    }

    int n;
    switch (random.nextInt(5)) {
        case 0: n = 0; break;
        case 1: n = Integer.MAX_VALUE; break;
        case 2: n = Integer.MIN_VALUE; break;
        case 3: n = 170 + random.nextInt(21); break; // around example thresholds
        default: n = random.nextInt(401) - 200; break;
    }

    return new Object[]{dict, n};
}

