    switch (choice) {
        case 0:
            // Normal random values within reasonable range
            a = random.nextInt(2001) - 1000; // -1000 to 1000
            b = random.nextInt(2001) - 1000;
            break;
        case 1:
            // Boundaries: 0, 1, -1, and extremes
            int[] boundaries = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
            a = boundaries[random.nextInt(boundaries.length)];
            b = boundaries[random.nextInt(boundaries.length)];
            break;
        case 2:
            // One zero, one random
            a = random.nextBoolean() ? 0 : (random.nextInt(2001) - 1000);
            b = random.nextBoolean() ? 0 : (random.nextInt(2001) - 1000);
            if (a != 0 && b != 0) {
                // ensure at least one zero
                if (random.nextBoolean()) {
                    a = 0;
                } else {
                    b = 0;
                }
            }
            break;
        case 3:
            // Both same sign or both negative
            if (random.nextBoolean()) {
                a = random.nextInt(1001); // 0 to 1000
                b = random.nextInt(1001);
            } else {
                a = -random.nextInt(1001); // -1000 to 0
                b = -random.nextInt(1001);
            }
            break;
        default:
            // Large values to test overflow behavior (though result may be Infinity)
            a = random.nextInt(100000) * (random.nextBoolean() ? 1 : -1);
            b = random.nextInt(100000) * (random.nextBoolean() ? 1 : -1);
            break;
    }
    return new Object[]{a, b};
}

