public static Object[] generateValidInput(Random random) {
    int a, b;
    int choice = random.nextInt(10);
    switch (choice) {
        case 0: // Same numbers (zero bits differ)
            a = random.nextInt();
            b = a;
            break;
        case 1: // Differ at exactly one bit (positive small)
            a = random.nextInt(1000);
            b = a ^ (1 << random.nextInt(31));
            break;
        case 2: // Differ at exactly one bit (negative)
            a = -random.nextInt(1000);
            b = a ^ (1 << random.nextInt(31));
            break;
        case 3: // Differ at multiple bits (random)
            a = random.nextInt();
            b = random.nextInt();
            break;
        case 4: // Boundary: 0 and 1
            a = 0;
            b = 1;
            break;
        case 5: // Boundary: 0 and 0
            a = 0;
            b = 0;
            break;
        case 6: // Boundary: Integer.MAX_VALUE and Integer.MIN_VALUE
            a = Integer.MAX_VALUE;
            b = Integer.MIN_VALUE;
            break;
        case 7: // Boundary: -1 and 0
            a = -1;
            b = 0;
            break;
        case 8: // Boundary: Integer.MAX_VALUE and Integer.MAX_VALUE-1
            a = Integer.MAX_VALUE;
            b = Integer.MAX_VALUE - 1;
            break;
        default: // Random edge: differ at highest bit
            a = random.nextInt();
            b = a ^ Integer.MIN_VALUE;
            break;
    }
    return new Object[]{a, b};
}

