public static Object[] generateValidInput(Random random) {
    int rows = random.nextInt(5); // 0 to 4 rows
    String[][] tupleStr = new String[rows][];

    for (int i = 0; i < rows; i++) {
        int cols = random.nextInt(4); // 0 to 3 columns
        tupleStr[i] = new String[cols];
        for (int j = 0; j < cols; j++) {
            // Generate values covering edge cases
            int choice = random.nextInt(7);
            switch (choice) {
                case 0:
                    tupleStr[i][j] = "0";
                    break;
                case 1:
                    tupleStr[i][j] = "1";
                    break;
                case 2:
                    tupleStr[i][j] = "-1";
                    break;
                case 3:
                    tupleStr[i][j] = String.valueOf(Integer.MAX_VALUE);
                    break;
                case 4:
                    tupleStr[i][j] = String.valueOf(Integer.MIN_VALUE);
                    break;
                case 5:
                    // Random number between -100 and 100
                    tupleStr[i][j] = String.valueOf(random.nextInt(201) - 100);
                    break;
                default:
                    // Random larger number
                    tupleStr[i][j] = String.valueOf(random.nextInt(2000000) - 1000000);
                    break;
            }
        }
    }

    // Occasionally include null as single-element array or null inner arrays
    if (rows > 0 && random.nextBoolean()) {
        int nullRow = random.nextInt(rows);
        if (random.nextBoolean()) {
            tupleStr[nullRow] = null;
        } else if (tupleStr[nullRow] != null && tupleStr[nullRow].length > 0) {
            tupleStr[nullRow][random.nextInt(tupleStr[nullRow].length)] = null;
        }
    }

    return new Object[]{tupleStr};
}

