        case 5:
            return new Object[]{"polygon", "y", "l"};
        case 6:
            return new Object[]{"character", "c", "a"};
        case 7:
            return new Object[]{"abcabc", "ab", "xy"};
        case 8:
            return new Object[]{"abcd", "a", "a"};
        default:
            String alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
            int targetIndex = random.nextInt(alphabet.length());
            char target = alphabet.charAt(targetIndex);
            int offset = 1 + random.nextInt(alphabet.length() - 1);
            char notTarget = alphabet.charAt((targetIndex + offset) % alphabet.length());

            int len = 2 + random.nextInt(10);
            StringBuilder str = new StringBuilder();
            for (int i = 0; i < len; i++) {
                if (i == 0) {
                    str.append(target);
                } else if (i == 1) {
                    str.append(notTarget);
                } else {
                    str.append(alphabet.charAt(random.nextInt(alphabet.length())));
                }
            }

            String ch = String.valueOf(target);
            String newch = String.valueOf(alphabet.charAt(random.nextInt(alphabet.length())));
            return new Object[]{str.toString(), ch, newch};
    }
}

