import java.math.*;

class CountOddSquares {

    /*@ requires n >= 0;
      @ requires n <= m;
      @ requires m < Integer.MAX_VALUE;
      @ ensures \result == (\num_of int k; n <= k && k <= m;
      @                         (\exists int r; 0 <= r && r <= 46340; r * r == k));
      @ assignable \nothing;
      @*/
    public static int countOddSquares(int n, int m) {
        int count = 0;
        /*@ loop_invariant 0 <= count && count <= m - n + 1;
          @ loop_invariant count == (\num_of int k; n <= k && k < i;
          @                               (\exists int r; 0 <= r && r <= 46340; r * r == k));
          @ loop_invariant i >= n && i <= m + 1;
          @ decreasing m - i + 1;
          @*/
        for (int i = n; i <= m; i++) {
            double square = Math.sqrt(i);
            if (square % 1 == 0 && i % 1 == 0) {
                count++;
            }
        }
        return count;
    }
}

