            arr = new int[0];
            k = random.nextInt(100) - 50;
            break;
        case 1: // null array
            arr = null;
            k = random.nextInt(100) - 50;
            break;
        case 2: // single element, k present
            int val = random.nextInt(100) - 50;
            arr = new int[]{val};
            k = val;
            break;
        case 3: // single element, k not present
            int val2 = random.nextInt(100) - 50;
            arr = new int[]{val2};
            do {
                k = random.nextInt(100) - 50;
            } while (k == val2);
            break;
        case 4: // multiple elements, k present at a random position
            int len = random.nextInt(10) + 2;
            arr = new int[len];
            int pos = random.nextInt(len);
            k = random.nextInt(100) - 50;
            arr[pos] = k;
            for (int i = 0; i < len; i++) {
                if (i != pos) {
                    int randVal;
                    do {
                        randVal = random.nextInt(100) - 50;
                    } while (randVal == k);
                    arr[i] = randVal;
                }
            }
            break;
        case 5: // multiple elements, k not present
            len = random.nextInt(10) + 2;
            arr = new int[len];
            k = random.nextInt(100) - 50;
            for (int i = 0; i < len; i++) {
                int randVal;
                do {
                    randVal = random.nextInt(100) - 50;
                } while (randVal == k);
                arr[i] = randVal;
            }
            break;
        case 6: // boundary values for k
            int[] specialK = {Integer.MIN_VALUE, Integer.MAX_VALUE, 0, 1, -1, 100, -100};
            k = specialK[random.nextInt(specialK.length)];
            len = random.nextInt(5) + 1;
            arr = new int[len];
            if (random.nextBoolean()) {
                // k present
                int pos2 = random.nextInt(len);
                arr[pos2] = k;
                for (int i = 0; i < len; i++) {
                    if (i != pos2) {
                        arr[i] = random.nextInt(100) - 50;
                    }
                }
            } else {
                // k not present
                for (int i = 0; i < len; i++) {
                    int randVal;
                    do {
                        randVal = random.nextInt(100) - 50;
                    } while (randVal == k);
                    arr[i] = randVal;
                }
            }
            break;
        case 7: // array with special values
            len = random.nextInt(5) + 1;
            arr = new int[len];
            int[] specialVals = {Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1};
            for (int i = 0; i < len; i++) {
                if (random.nextBoolean()) {
                    arr[i] = specialVals[random.nextInt(specialVals.length)];
                } else {
                    arr[i] = random.nextInt(100) - 50;
                }
            }
            if (random.nextBoolean()) {
