    int choice = random.nextInt(10);
    int x, y, z;

    switch (choice) {
        case 0:
            // All equal
            x = y = z = random.nextInt(2001) - 1000;
            break;
        case 1:
            // x == y only
            x = y = random.nextInt(2001) - 1000;
            z = random.nextInt(2001) - 1000;
            while (z == x) {
                z = random.nextInt(2001) - 1000;
            }
            break;
        case 2:
            // y == z only
            y = z = random.nextInt(2001) - 1000;
            x = random.nextInt(2001) - 1000;
            while (x == y) {
                x = random.nextInt(2001) - 1000;
            }
            break;
        case 3:
            // x == z only
            x = z = random.nextInt(2001) - 1000;
            y = random.nextInt(2001) - 1000;
            while (y == x) {
                y = random.nextInt(2001) - 1000;
            }
            break;
        case 4:
            // All different
            x = random.nextInt(2001) - 1000;
            do {
                y = random.nextInt(2001) - 1000;
            } while (y == x);
            do {
                z = random.nextInt(2001) - 1000;
            } while (z == x || z == y);
            break;
        case 5:
            // Boundary: all equal at MAX_VALUE
            x = y = z = Integer.MAX_VALUE;
            break;
        case 6:
            // Boundary: all equal at MIN_VALUE
            x = y = z = Integer.MIN_VALUE;
            break;
        case 7:
            // Boundary: all equal at 0
            x = y = z = 0;
            break;
        case 8:
            // Boundary: all equal at 1 and -1
            if (random.nextBoolean()) {
                x = y = z = 1;
            } else {
                x = y = z = -1;
            }
            break;
        default:
            // Mixed extremes
            x = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            y = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            if (x == y) {
                z = (x == Integer.MAX_VALUE) ? Integer.MIN_VALUE : Integer.MAX_VALUE;
            } else {
                z = x; // creates a pair
            }
            break;
    }

    return new Object[]{x, y, z};
}

