            int val = random.nextInt(200) - 100;
            int len2 = random.nextInt(20) + 1;
            array = new int[len2];
            java.util.Arrays.fill(array, val);
            break;
        case 3:
            // Boundary values including Integer.MAX_VALUE and Integer.MIN_VALUE
            array = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, 0, -1, 1, Integer.MAX_VALUE, Integer.MIN_VALUE};
            break;
        case 4:
            // Minimum at first position
            array = new int[]{Integer.MIN_VALUE, random.nextInt(200) - 100, random.nextInt(200) - 100};
            break;
        default:
            // Minimum at last position
            array = new int[]{random.nextInt(200) - 100, random.nextInt(200) - 100, Integer.MIN_VALUE};
            break;
    }
    return new Object[]{array};
}

