            if (special == 0) {
                arr[i][j] = Integer.MIN_VALUE;
            } else if (special == 1) {
                arr[i][j] = Integer.MAX_VALUE;
            } else if (special == 2) {
                arr[i][j] = 0;
            } else if (special == 3) {
                arr[i][j] = -1;
            } else if (special == 4) {
                arr[i][j] = 1;
            } else {
                arr[i][j] = random.nextInt(2001) - 1000; // -1000 to 1000
            }
        }
    }
    return new Object[]{arr};
}

