public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(6);
    int[] nums;
    switch (choice) {
        case 0:
            // Empty array
            nums = new int[0];
            break;
        case 1:
            // Single digit
            nums = new int[]{random.nextInt(10)};
            break;
        case 2:
            // Multiple digits with possible zeros
            int len = 1 + random.nextInt(9);
            nums = new int[len];
            for (int i = 0; i < len; i++) {
                nums[i] = random.nextInt(10);
            }
            break;
        case 3:
            // Boundary: all zeros
            nums = new int[]{0, 0, 0};
            break;
        case 4:
            // Boundary: all nines (max possible)
            nums = new int[]{9, 9, 9, 9, 9, 9, 9, 9, 9, 9};
            break;
        default:
            // Random length with digits 0-9
            int randomLen = random.nextInt(10);
            nums = new int[randomLen];
            for (int i = 0; i < randomLen; i++) {
                nums[i] = random.nextInt(10);
            }
            break;
    }
    return new Object[]{nums};
}

