public static Object[] generateValidInput(Random random) {
    int L;
    // Decide array length: 10% chance of empty array, otherwise 1-10
    if (random.nextInt(10) == 0) {
        L = 0;
    } else {
        L = random.nextInt(10) + 1; // 1 to 10
    }

    int[] arr;
    int n, k;

    if (L == 0) {
        arr = new int[0];
        n = 0;
        // Cover both branches: k <= n (false) and k > n (true)
        k = random.nextBoolean() ? 0 : 1;
    } else {
        // Choose a valid final index after adjustment (1-based)
        int finalK = random.nextInt(L) + 1; // 1..L
        boolean branch = random.nextBoolean(); // true: k > n, false: k <= n

        if (branch) {
            // k > n branch: k = n + finalK, finalK = k - n
            // n is generated in a safe range to avoid overflow
            n = random.nextInt(21) - 10; // -10 to 10
            k = n + finalK;
        } else {
            // k <= n branch: k = finalK, n must be >= finalK
            n = finalK + random.nextInt(10); // finalK to finalK+9
            k = finalK;
        }

        // Fill the array with random integers
        arr = new int[L];
        for (int i = 0; i < L; i++) {
            arr[i] = random.nextInt(); // any int value
        }
    }

    // Return parameters in correct order: array, n, k
    return new Object[]{arr, n, k};
}

