public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(8);
    Object[] testTup;

    switch (choice) {
        case 0: // Normal case with one nested array
            testTup = new Object[]{
                random.nextInt(100),
                random.nextInt(100),
                random.nextInt(100),
                new Object[]{random.nextInt(100), random.nextInt(100)},
                random.nextInt(100)
            };
            break;
        case 1: // Multiple nested arrays
            testTup = new Object[]{
                random.nextInt(100),
                new Object[]{random.nextInt(100), random.nextInt(100)},
                random.nextInt(100),
                new Object[]{random.nextInt(100), random.nextInt(100), random.nextInt(100)},
                random.nextInt(100)
            };
            break;
        case 2: // Boundary values
            testTup = new Object[]{
                Integer.MIN_VALUE,
                Integer.MAX_VALUE,
                0,
                -1,
                new Object[]{Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1}
            };
            break;
        case 3: // Empty array
            testTup = new Object[]{};
            break;
        case 4: // Only nested arrays (no direct integers)
            testTup = new Object[]{
                new Object[]{random.nextInt(100)},
                new Object[]{},
                new Object[]{random.nextInt(100), random.nextInt(100)}
            };
            break;
        case 5: // Null elements
            testTup = new Object[]{
                null,
                random.nextInt(100),
                null,
                new Object[]{null, random.nextInt(100)},
                random.nextInt(100)
            };
            break;
        case 6: // Mixed types (including non-Integer objects)
            testTup = new Object[]{
                "string",
                random.nextInt(100),
                new Object[]{"nested", random.nextInt(100)},
                3.14,
                random.nextInt(100)
            };
            break;
        case 7: // Large array with random mix
            int size = random.nextInt(10) + 1;
            testTup = new Object[size];
            for (int i = 0; i < size; i++) {
                if (random.nextBoolean()) {
                    testTup[i] = random.nextInt(200) - 100;
                } else {
                    testTup[i] = new Object[]{random.nextInt(100), random.nextInt(100)};
                }
            }
            break;
        default:
            testTup = new Object[]{};
    }

    return new Object[]{testTup};
}

