import java.io.*;
import java.lang.*;
import java.math.*;

class FindPeak {

    //@ requires n >= 1 && n <= arr.length;
    //@ ensures \result >= 0 && \result < n;
    //@ ensures \result + 1 >= n || arr[\result] >= arr[\result + 1];
    //@ assignable \nothing;
    public static int findPeak(int[] arr, int n) {
        int left = 0, right = n - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < arr[mid + 1]) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

