                } else if (valueType == 1) {
                    nums[i] = -(random.nextInt(100) + 1);
                } else if (valueType == 2) {
                    nums[i] = 0;
                } else {
                    nums[i] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                }
            }
            return new Object[]{nums};
    }
}

