            lst = new int[0][0];
            break;
        case 1: // array with one empty sublist
            lst = new int[1][0];
            break;
        case 2: // single sublist of length 1 containing 0
            lst = new int[][]{{0}};
            break;
        case 3: // single sublist of length 1 containing non-zero
            lst = new int[][]{{1}};
            break;
        case 4: // multiple sublists, some with zeros, random lengths
            int rows = random.nextInt(5) + 1; // 1 to 5
            lst = new int[rows][];
            for (int i = 0; i < rows; i++) {
                int cols = random.nextInt(6); // 0 to 5
                lst[i] = new int[cols];
                for (int j = 0; j < cols; j++) {
                    if (random.nextDouble() < 0.3) {
                        lst[i][j] = 0;
                    } else {
                        lst[i][j] = random.nextInt(201) - 100; // -100 to 100
                    }
                }
            }
            break;
        case 5: // sublist containing all zeros
            int len = random.nextInt(5) + 1; // 1 to 5
            lst = new int[1][len];
            break;
        case 6: // large values and no zeros
            lst = new int[][]{
                {Integer.MAX_VALUE, Integer.MIN_VALUE, -1, 1, 1000}
            };
            break;
        case 7: // random with at least one zero-free sublist of positive length
            rows = random.nextInt(5) + 1; // 1 to 5
            lst = new int[rows][];
            int zeroFreeRow = random.nextInt(rows);
            for (int i = 0; i < rows; i++) {
                int cols;
                if (i == zeroFreeRow) {
                    cols = random.nextInt(5) + 1; // ensure at least 1
                } else {
                    cols = random.nextInt(6); // 0 to 5
                }
                lst[i] = new int[cols];
                for (int j = 0; j < cols; j++) {
                    if (i == zeroFreeRow) {
                        // no zeros
                        lst[i][j] = random.nextInt(200) + 1; // 1 to 200
                    } else {
                        if (random.nextDouble() < 0.3) {
                            lst[i][j] = 0;
                        } else {
                            lst[i][j] = random.nextInt(201) - 100; // -100 to 100
                            if (lst[i][j] == 0) lst[i][j] = 1; // avoid accidental zero
                        }
                    }
                }
            }
            break;
        case 8: // null
            lst = null;
            break;
        default:
            lst = new int[][]{{}}; // fallback
    }
    return new Object[]{lst};
}

