    int caseType = random.nextInt(8); // 0-7 to cover more edge cases

    int[] a;
    int[] b;
    int n;
    int m;

    switch (caseType) {
        case 0: // Normal case: b is a subarray of a (true)
            n = random.nextInt(5) + 2; // a length between 2 and 6
            m = random.nextInt(n) + 1; // b length between 1 and n
            a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = random.nextInt(11) - 5; // values -5 to 5
            }
            // Choose a random start index for b inside a
            int start = random.nextInt(n - m + 1);
            b = new int[m];
            for (int j = 0; j < m; j++) {
                b[j] = a[start + j];
            }
            break;

        case 1: // Normal case: b is not a subarray (false)
            n = random.nextInt(5) + 2;
            m = random.nextInt(n) + 1;
            a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = random.nextInt(11) - 5;
            }
            // Generate b with at least one element different from any possible subarray
            b = new int[m];
            for (int j = 0; j < m; j++) {
                b[j] = random.nextInt(11) - 5;
            }
            // Ensure b is not a subarray by modifying one element to be different from a
            if (m <= n) {
                // Modify a random position in b to be something that cannot match
                int pos = random.nextInt(m);
                // Find a value that is not equal to a[pos] (if possible)
                int target = a[pos % n];
                int newVal = (target + 1) % 11 - 5; // cycle to a different value
                if (newVal == target) newVal = (target + 2) % 11 - 5;
                b[pos] = newVal;
            }
            break;

        case 2: // Empty arrays
            if (random.nextBoolean()) {
                a = new int[0];
                n = 0;
                b = new int[random.nextInt(3)];
                m = b.length;
            } else {
                b = new int[0];
                m = 0;
                a = new int[random.nextInt(3)];
                n = a.length;
            }
            break;

        case 3: // Null arrays
            if (random.nextBoolean()) {
                a = null;
                n = random.nextInt(5);
                b = new int[random.nextInt(3)];
                m = b.length;
            } else {
                b = null;
                m = random.nextInt(5);
                a = new int[random.nextInt(3)];
                n = a.length;
            }
            break;

        case 4: // n < m (should return false)
            n = random.nextInt(3); // 0-2
            m = n + random.nextInt(3) + 1; // m > n
            a = new int[n];
            for (int i = 0; i < n; i++) a[i] = random.nextInt(11) - 5;
            b = new int[m];
            for (int j = 0; j < m; j++) b[j] = random.nextInt(11) - 5;
            break;

        case 5: // Negative lengths or large values
            if (random.nextBoolean()) {
                n = -random.nextInt(5) - 1;
                m = random.nextInt(5);
            } else {
                m = -random.nextInt(5) - 1;
                n = random.nextInt(5);
            }
            // Generate arrays with arbitrary lengths (but not negative)
            int alen = Math.max(0, random.nextInt(5));
            int blen = Math.max(0, random.nextInt(5));
            a = new int[alen];
            b = new int[blen];
            for (int i = 0; i < alen; i++) a[i] = random.nextInt(11) - 5;
            for (int j = 0; j < blen; j++) b[j] = random.nextInt(11) - 5;
            // Note: n and m may not match array lengths, testing robustness
            break;

        case 6: // Single element arrays
            n = 1;
            m = 1;
            a = new int[1];
            a[0] = random.nextInt(11) - 5;
            if (random.nextBoolean()) {
                b = new int[1];
                b[0] = a[0]; // true
            } else {
                b = new int[1];
                b[0] = a[0] + 1; // false
            }
            break;

        case 7: // All same values
            int val = random.nextInt(11) - 5;
            n = random.nextInt(5) + 1;
            m = random.nextInt(n) + 1;
            a = new int[n];
            for (int i = 0; i < n; i++) a[i] = val;
            b = new int[m];
            for (int j = 0; j < m; j++) b[j] = val;
            // b is always a subarray (since all same)
            break;

        default: // fallback
            n = random.nextInt(5) + 1;
            m = random.nextInt(n) + 1;
            a = new int[n];
            b = new int[m];
            for (int i = 0; i < n; i++) a[i] = random.nextInt(11) - 5;
            for (int j = 0; j < m; j++) b[j] = random.nextInt(11) - 5;
            break;
    }

    // Wrap ints in Integer
    return new Object[]{a, b, Integer.valueOf(n), Integer.valueOf(m)};
