                else if (val == 1) arr[i] = Integer.MIN_VALUE;
                else arr[i] = random.nextInt(1000) + 1;
            }
            lens = random.nextInt(len) + 1; // 1..len
            n = random.nextInt(20) + 1;
            break;
        case 6: // n = 1 (remainder always 0)
            len = random.nextInt(5) + 1;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt(200) - 100;
