      @   requires r > 0;
      @   ensures \result == (int) Math.sqrt(3) * r * r;
      @*/
    public static int triangleArea(int r) {
        int area = 0;
        if (r < 0) {
            return -1;
        } else if (r == 0) {
            area = 0;
        } else {
            area = (int) Math.sqrt(3) * r * r;
        }
        return area;
    }
}

