public static Object[] generateValidInput(Random random) {
    int caseType = random.nextInt(6);
    int n;
    int[] arr;
    int[] dep;

    switch (caseType) {
        case 0: // Empty arrays
            n = 0;
            arr = new int[0];
            dep = new int[0];
            break;
        case 1: // Single train
            n = 1;
            arr = new int[]{random.nextInt(1000)};
            dep = new int[]{arr[0] + random.nextInt(100)};
            break;
        case 2: // All departures before arrivals (no overlap)
            n = random.nextInt(5) + 1;
            arr = new int[n];
            dep = new int[n];
            int base = random.nextInt(1000);
            for (int i = 0; i < n; i++) {
                dep[i] = base + i * 10;
                arr[i] = dep[i] + random.nextInt(5) + 1;
            }
            break;
        case 3: // All trains overlap (same time)
            n = random.nextInt(5) + 1;
            arr = new int[n];
            dep = new int[n];
            int time = random.nextInt(1000);
            for (int i = 0; i < n; i++) {
                arr[i] = time;
                dep[i] = time + random.nextInt(10) + 1;
            }
            break;
        case 4: // Mixed intervals with random times
            n = random.nextInt(8) + 1;
            arr = new int[n];
            dep = new int[n];
            for (int i = 0; i < n; i++) {
                int start = random.nextInt(2000);
                arr[i] = start;
                dep[i] = start + random.nextInt(100);
            }
            break;
        default: // Boundary values with max/min
            n = random.nextInt(6) + 1;
            arr = new int[n];
            dep = new int[n];
            for (int i = 0; i < n; i++) {
                int start = random.nextBoolean() ? random.nextInt(100) : (random.nextInt(100) + Integer.MAX_VALUE - 100);
                arr[i] = start;
                dep[i] = start + (random.nextBoolean() ? 1 : random.nextInt(100));
                if (dep[i] < 0) dep[i] = Integer.MAX_VALUE;
            }
            break;
    }

    return new Object[]{arr, dep, n};
}

