public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(6);
    String str1;
    String str2;

    switch (choice) {
        case 0: // both empty strings
            str1 = "";
            str2 = "";
            break;
        case 1: // one empty, one non-empty
            str1 = "";
            str2 = generateRandomString(random, random.nextInt(5) + 1);
            break;
        case 2: // permutations of same string
            String base = generateRandomString(random, random.nextInt(8) + 1);
            str1 = base;
            str2 = shuffleString(base, random);
            break;
        case 3: // different lengths
            str1 = generateRandomString(random, random.nextInt(8) + 1);
            str2 = generateRandomString(random, random.nextInt(8) + 1);
            if (str1.length() == str2.length()) {
                str2 += "a";
            }
            break;
        case 4: // same length but not permutations (guarantee false)
            str1 = generateRandomString(random, random.nextInt(8) + 1);
            str2 = generateRandomString(random, str1.length());
            // Ensure at least one character difference
            if (str1.equals(str2)) {
                if (str2.length() > 0) {
                    str2 = str2.substring(0, str2.length() - 1) + (char)('a' + random.nextInt(26));
                } else {
                    str2 = "a";
                }
            }
            break;
        default: // random strings with random lengths
            str1 = generateRandomString(random, random.nextInt(10));
            str2 = generateRandomString(random, random.nextInt(10));
            break;
    }

    return new Object[]{str1, str2};
}

private static String generateRandomString(Random random, int length) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        sb.append((char)('a' + random.nextInt(26)));
    }
    return sb.toString();
}

private static String shuffleString(String s, Random random) {
    char[] chars = s.toCharArray();
    for (int i = chars.length - 1; i > 0; i--) {
        int j = random.nextInt(i + 1);
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
    }
    return new String(chars);
}

