            }
            break;
        case 1: // Both empty arrays
            arr1 = new int[0];
            arr2 = new int[0];
            break;
        case 2: // One empty, one non-empty
            arr1 = new int[0];
            arr2 = new int[]{random.nextInt(100) - 50};
            break;
        case 3: // Equal lengths with boundary values
            int len = random.nextInt(5) + 1;
            arr1 = new int[len];
            arr2 = new int[len];
            for (int i = 0; i < len; i++) {
                switch (random.nextInt(4)) {
                    case 0: arr1[i] = Integer.MAX_VALUE; break;
                    case 1: arr1[i] = Integer.MIN_VALUE; break;
                    case 2: arr1[i] = 0; break;
                    default: arr1[i] = 1; break;
                }
                switch (random.nextInt(4)) {
                    case 0: arr2[i] = Integer.MAX_VALUE; break;
                    case 1: arr2[i] = Integer.MIN_VALUE; break;
                    case 2: arr2[i] = 0; break;
                    default: arr2[i] = 1; break;
                }
            }
            break;
        case 4: // Single element arrays
            arr1 = new int[]{random.nextInt(200) - 100};
            arr2 = new int[]{random.nextInt(200) - 100};
            break;
        default: // Different lengths, one much longer
            int shortLen = random.nextInt(3) + 1;
            int longLen = shortLen + random.nextInt(5) + 2;
            arr1 = new int[shortLen];
            arr2 = new int[longLen];
            for (int i = 0; i < shortLen; i++) {
                arr1[i] = random.nextInt(100);
            }
            for (int i = 0; i < longLen; i++) {
                arr2[i] = random.nextInt(100);
            }
            break;
    }

    return new Object[]{arr1, arr2};
}

