        "{({()})}", "(((())))", "[()]{}{[()()]()}", "{{[[(())]]}}"
    };
    String[] invalidPatterns = {
        "(", ")", "{", "}", "[", "]", "())", "(()", "{[}]", "([)]",
        "((}", "([)]", "(){", "[])", "[}", "(()))", "{{}", "[]]",
        "([)]", "{[}", "(){}[", "(){}]", "[()]", "({)}"
    };

    int choice = random.nextInt(5); // Expanded to cover more branches
    String input;

    if (choice == 0 && validPatterns.length > 0) {
        input = validPatterns[random.nextInt(validPatterns.length)];
    } else if (choice == 1 && invalidPatterns.length > 0) {
        input = invalidPatterns[random.nextInt(invalidPatterns.length)];
    } else if (choice == 2) {
        // Generate random string with mixed characters
        StringBuilder sb = new StringBuilder();
        int len = random.nextInt(10);
        char[] chars = {'(', ')', '{', '}', '[', ']'};
        for (int i = 0; i < len; i++) {
            sb.append(chars[random.nextInt(chars.length)]);
        }
        input = sb.toString();
    } else if (choice == 3) {
        // Include characters that are not parentheses
        StringBuilder sb = new StringBuilder();
        int len = random.nextInt(5);
        char[] chars = {'a', 'b', 'c', '1', '2', ' ', '\n'};
        for (int i = 0; i < len; i++) {
            sb.append(chars[random.nextInt(chars.length)]);
        }
        input = sb.toString();
    } else {
        // Generate empty string or null
        if (random.nextBoolean()) {
            input = "";
        } else {
            input = null;
        }
    }

    // Occasionally test null
    if (random.nextInt(10) == 0) {
        input = null;
    }

    return new Object[]{input};
}

