      @   ensures \result != -1 ==> a[\result] == x;
      @   ensures \result != -1 ==> (\forall int i; \result < i && i < a.length; a[i] != x);
      @   ensures \result == -1 ==> (\forall int i; 0 <= i && i < a.length; a[i] != x);
