public static Object[] generateValidInput(Random random) {
    int[] numbers;
    int caseType = random.nextInt(5);

    switch (caseType) {
        case 0:
            // Normal case with random positive and negative numbers
            int len1 = random.nextInt(10) + 1;
            numbers = new int[len1];
            for (int i = 0; i < len1; i++) {
                numbers[i] = random.nextInt(2001) - 1000;
            }
            break;
        case 1:
            // Boundary case: single element (0, 1, -1)
            int value = random.nextInt(3) - 1; // -1, 0, or 1
            numbers = new int[]{value};
            break;
        case 2:
            // Boundary case: array with Integer.MAX_VALUE and Integer.MIN_VALUE
            numbers = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, 0};
            break;
        case 3:
            // Edge case: all zeros
            int len3 = random.nextInt(5) + 1;
            numbers = new int[len3];
            break;
        case 4:
            // Edge case: large array with mixed values including extremes
            int len4 = random.nextInt(100) + 50;
            numbers = new int[len4];
            for (int i = 0; i < len4; i++) {
                if (random.nextBoolean()) {
                    numbers[i] = random.nextInt(10001) - 5000;
                } else {
                    numbers[i] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
                }
            }
            break;
        default:
            // Default: simple array
            numbers = new int[]{8, 2, 3, 0, 7};
            break;
    }

    return new Object[]{numbers};
}

