import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class BinarySearch {

    /*@ requires itemArray != null;
      @ requires (\forall int i, j; 0 <= i && i < j && j < itemArray.length; 
      @             itemArray[i] <= itemArray[j]);
      @ ensures \result != null;
      @ ensures \result.booleanValue() <==> 
      @         (\exists int i; 0 <= i && i < itemArray.length; 
      @          itemArray[i] == item);
      @ ensures !\result.booleanValue() <==> 
      @         !(\exists int i; 0 <= i && i < itemArray.length; 
      @           itemArray[i] == item);
      @ assignable \nothing;
      @*/
    public static Boolean binarySearch(int[] itemArray, int item) {
        int low = 0;
        int high = itemArray.length - 1;
        /*@ loop_invariant 0 <= low && low <= high + 1 && high < itemArray.length;
          @ loop_invariant (\forall int i; 0 <= i && i < low; 
          @                   itemArray[i] < item);
          @ loop_invariant (\forall int i; high < i && i < itemArray.length; 
          @                   itemArray[i] > item);
          @ decreases high - low + 1;
          @*/
        while (low <= high) {
            int mid = (low + high) / 2;
            if (item == itemArray[mid]) {
                return true;
            } else if (item < itemArray[mid]) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return false;
    }
}

