import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class DecimalToOctal {

    //@ requires decinum >= 0 && decinum <= 511;
    //@ ensures \result >= 0;
    //@ ensures decinum == 0 ==> \result == 0;
    //@ ensures decinum > 0 ==> \result > 0;
