import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class DecimalToOctal {

    //@ requires decinum >= 0;
    //@ requires decinum < 01000000000;
    //@ ensures \result >= 0;
    //@ ensures decinum == 0 ==> \result == 0;
    public static int decimalToOctal(int decinum) {
        int octal = 0;
        int rem = 0;
        int i = 0;
        while (decinum != 0) {
            rem = decinum % 8;
            octal = octal + rem * (int) Math.pow(10, i);
            decinum = decinum / 8;
            i++;
        }
        return octal;
    }
}

