public static Object[] generateValidInput(Random random) {
    // Generate diverse inputs covering normal, boundary, and edge cases.
    int[] candidateValues = {
        0,                      // Zero
        1,                      // Smallest positive
        -1,                     // Negative (all bits set)
        Integer.MAX_VALUE,      // Large positive
        Integer.MIN_VALUE,      // Large negative (only MSB set)
        2,                      // Power of two (bit1)
        3,                      // Two consecutive bits
        5,                      // 101 binary
        10,                     // Example from description
        20,                     // Example from description
        30,                     // Example from description
        0x55555555,             // Alternating bits (even positions set)
        0xAAAAAAAA,             // Alternating bits (odd positions set)
        0xFFFFFFFF,             // All bits set
        0x00000000,             // All bits cleared
        random.nextInt(),       // Random integer
        random.nextInt(1024),   // Small random
        random.nextInt(1 << 20) // Medium random
    };

    // Pick one candidate randomly to ensure diverse coverage
    int n = candidateValues[random.nextInt(candidateValues.length)];

    // Return the parameter in an Object array
    return new Object[]{n};
}

