            return new Object[]{arr1, arr2};

        case 1: // Edge case: first array is empty
            int[] emptyArr1 = new int[0];
            int[] arr2Case1 = new int[random.nextInt(5) + 1];
            for (int i = 0; i < arr2Case1.length; i++) {
                arr2Case1[i] = random.nextInt();
            }
