public static Object[] generateValidInput(Random random) {
    // Decide which category of input to generate
    int category = random.nextInt(10);

    List<Integer> testTup1 = null;
    List<Integer> testTup2 = null;

    switch (category) {
        case 0: // Both empty lists
            testTup1 = new ArrayList<>();
            testTup2 = new ArrayList<>();
            break;
        case 1: // First list null, second non-null with random values
            testTup1 = null;
            testTup2 = generateRandomList(random, random.nextInt(5) + 1);
            break;
        case 2: // Second list null, first non-null
            testTup1 = generateRandomList(random, random.nextInt(5) + 1);
            testTup2 = null;
            break;
        case 3: // Both null
            testTup1 = null;
            testTup2 = null;
            break;
        case 4: // Different sizes (first longer, second shorter)
            int size1 = random.nextInt(5) + 2; // at least 2
            int size2 = random.nextInt(size1); // smaller than size1
            testTup1 = generateRandomList(random, size1);
            testTup2 = generateRandomList(random, size2);
            break;
        case 5: // Same size with boundary values
            int size = random.nextInt(4) + 1; // 1 to 4
            testTup1 = new ArrayList<>();
            testTup2 = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                int val1 = pickBoundaryValue(random);
                int val2 = pickBoundaryValue(random);
                testTup1.add(val1);
                testTup2.add(val2);
            }
            break;
        case 6: // Normal random same size (small)
            int sz = random.nextInt(6) + 1; // 1 to 6
            testTup1 = generateRandomList(random, sz);
            testTup2 = generateRandomList(random, sz);
            break;
        case 7: // Same size with large random values
            int largeSize = random.nextInt(5) + 1;
            testTup1 = new ArrayList<>();
            testTup2 = new ArrayList<>();
            for (int i = 0; i < largeSize; i++) {
                testTup1.add(random.nextInt());
                testTup2.add(random.nextInt());
            }
            break;
        case 8: // One-element lists
            testTup1 = new ArrayList<>();
            testTup2 = new ArrayList<>();
            testTup1.add(random.nextInt());
            testTup2.add(random.nextInt());
            break;
        case 9: // Lists with negative values
            int negSize = random.nextInt(4) + 1;
            testTup1 = new ArrayList<>();
            testTup2 = new ArrayList<>();
            for (int i = 0; i < negSize; i++) {
                testTup1.add(-random.nextInt(1000) - 1);
                testTup2.add(-random.nextInt(1000) - 1);
            }
            break;
        default:
            // Fallback: normal random
            int defSize = random.nextInt(6) + 1;
            testTup1 = generateRandomList(random, defSize);
            testTup2 = generateRandomList(random, defSize);
            break;
    }

    return new Object[]{testTup1, testTup2};
}

// Helper to generate a random list of given size with random values
private static List<Integer> generateRandomList(Random random, int size) {
    List<Integer> list = new ArrayList<>();
    for (int i = 0; i < size; i++) {
        // With some probability, insert a boundary value
        if (random.nextInt(5) == 0) {
            list.add(pickBoundaryValue(random));
        } else {
            list.add(random.nextInt(2001) - 1000); // range -1000 to 1000
        }
    }
    return list;
}

// Helper to pick a boundary value
private static int pickBoundaryValue(Random random) {
    int choice = random.nextInt(6);
    switch (choice) {
        case 0: return 0;
        case 1: return 1;
        case 2: return -1;
        case 3: return Integer.MAX_VALUE;
        case 4: return Integer.MIN_VALUE;
        case 5: return random.nextInt(2001) - 1000; // random instead of fixed
        default: return 0;
    }
}

