public static Object[] generateValidInput(Random random) {
    String[] samples = {
        "",
        "   ",
        "a",
        "ab",
        "abc",
        "abcd",
        "abcde",
        "abcdef",
        "a ab abc abcd abcde abcdef",
        "one two three four five six seven",
        "For the four consumer complaints contact manager AKR reddy",
        "Certain service are subject to change MSR",
        "Third party legal desclaimers",
        "I am a cat with long whiskers",
        "a  b   c    d     e",
        "word, with, punctuation.",
        "single",
        "12 123 1234 12345 123456"
    };

    String text;
    if (random.nextBoolean()) {
        text = samples[random.nextInt(samples.length)];
    } else {
        int wordCount = random.nextInt(10);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < wordCount; i++) {
            if (i > 0) {
                int spaces = 1 + random.nextInt(4);
                for (int j = 0; j < spaces; j++) {
                    sb.append(' ');
                }
            }
            int len = random.nextInt(8);
            for (int j = 0; j < len; j++) {
                sb.append((char) ('a' + random.nextInt(26)));
            }
        }
        text = sb.toString();
    }

    return new Object[]{text};
}

