public static Object[] generateValidInput(Random random) {
    String[] pool = {
        "red", "green", "blue", "white", "black", "orange",
        "yellow", "purple", "pink", "brown", "gray", "cyan",
        "magenta", "lime", "gold", "silver", "maroon", "navy",
        "olive", "coral", "crimson", "khaki", "plum", "wheat",
        "tan", "turquoise", "orchid", "salmon", "sienna", "thistle",
        "tomato", "violet", ""
    };
    int poolLen = pool.length;

    // generate list1
    int len1 = random.nextInt(10); // 0..9
    String[] list1 = new String[len1];
    for (int i = 0; i < len1; i++) {
        if (random.nextDouble() < 0.1) {
            list1[i] = null;
        } else {
            list1[i] = pool[random.nextInt(poolLen)];
        }
    }

    // generate removeWords
    int len2 = random.nextInt(10); // 0..9
    String[] removeWords = new String[len2];

    // build candidate list from list1 and pool, plus null
    int totalCandidates = len1 + poolLen + 1;
    String[] candidates = new String[totalCandidates];
    int idx = 0;
    for (int i = 0; i < len1; i++) {
        candidates[idx++] = list1[i];
    }
    for (int i = 0; i < poolLen; i++) {
        candidates[idx++] = pool[i];
    }
    candidates[idx] = null; // last candidate is null

    // fill removeWords randomly from candidates
    for (int i = 0; i < len2; i++) {
        removeWords[i] = candidates[random.nextInt(totalCandidates)];
    }

    // occasionally force removeWords to contain all elements of list1 (to test empty result)
    if (len1 > 0 && random.nextDouble() < 0.1) {
        String[] newRemove = new String[len2];
        for (int i = 0; i < len2 && i < len1; i++) {
            newRemove[i] = list1[i % len1];
        }
        // fill remaining with random from pool
        for (int i = len1; i < len2; i++) {
            newRemove[i] = pool[random.nextInt(poolLen)];
        }
        removeWords = newRemove;
    }

    return new Object[]{list1, removeWords};
}

