public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(9); // 0-8
    int[] array;
    switch (choice) {
        case 0: // empty array
            array = new int[0];
            break;
        case 1: // single element
            array = new int[]{random.nextInt(200) - 100};
            break;
        case 2: // two elements
            array = new int[2];
            array[0] = random.nextInt(200) - 100;
            array[1] = random.nextInt(200) - 100;
            break;
        case 3: // already sorted
            int len = random.nextInt(15) + 1;
            array = new int[len];
            int prev = random.nextInt(200) - 100;
            for (int i = 0; i < len; i++) {
                array[i] = prev;
                prev += random.nextInt(5); // ensure non-decreasing
            }
            break;
        case 4: // reverse sorted
            len = random.nextInt(15) + 1;
            array = new int[len];
            prev = random.nextInt(200) - 100;
            for (int i = len - 1; i >= 0; i--) {
                array[i] = prev;
                prev += random.nextInt(5);
            }
            break;
        case 5: // random array with duplicates
            len = random.nextInt(10) + 5; // 5-14
            array = new int[len];
            for (int i = 0; i < len; i++) {
                array[i] = random.nextInt(20) - 10; // small range to create duplicates
            }
            break;
        case 6: // all same element
            len = random.nextInt(10) + 1;
            int val = random.nextInt(200) - 100;
            array = new int[len];
            Arrays.fill(array, val);
            break;
        case 7: // boundary values
            len = random.nextInt(5) + 1;
            array = new int[len];
            for (int i = 0; i < len; i++) {
                int r = random.nextInt(4);
                switch (r) {
                    case 0: array[i] = Integer.MIN_VALUE; break;
                    case 1: array[i] = Integer.MAX_VALUE; break;
                    case 2: array[i] = 0; break;
                    case 3: array[i] = random.nextBoolean() ? -1 : 1; break;
                }
            }
            break;
        case 8: // null
