    };

    int choice = random.nextInt(3);

    if (choice == 0) {
        // Return a valid integer string
        return new Object[]{validIntegers[random.nextInt(validIntegers.length)]};
    } else if (choice == 1) {
        // Return an invalid integer string
        return new Object[]{invalidIntegers[random.nextInt(invalidIntegers.length)]};
    } else {
        // Return a random string that could be either valid or invalid
        StringBuilder sb = new StringBuilder();
        int length = random.nextInt(8);
        for (int i = 0; i < length; i++) {
            char c = (char) (random.nextInt(95) + 32); // ASCII printable range
            sb.append(c);
        }
        return new Object[]{sb.toString()};
    }
}

