public static Object[] generateValidInput(Random random) {
    int a, b, n;
    int choice = random.nextInt(6);

    switch (choice) {
        case 0:
            // Normal random values with b > 0 to avoid division by zero
            b = random.nextInt(100) + 1;
            a = random.nextInt(200) - 100;
            n = random.nextInt(100);
            break;
        case 1:
            // Boundary: b = 1, n = 0
            b = 1;
            a = random.nextInt(200) - 100;
            n = 0;
            break;
        case 2:
            // Boundary: n = Integer.MAX_VALUE
            b = random.nextInt(100) + 1;
            a = random.nextInt(200) - 100;
            n = Integer.MAX_VALUE;
            break;
        case 3:
            // Boundary: a = 0
            b = random.nextInt(100) + 1;
            a = 0;
            n = random.nextInt(100);
            break;
        case 4:
            // Boundary: negative values
            b = -random.nextInt(100) - 1;
            a = random.nextInt(200) - 100;
            n = random.nextInt(100);
            break;
        default:
            // Edge: large values
            b = random.nextInt(Integer.MAX_VALUE) + 1;
            a = random.nextInt(Integer.MAX_VALUE) - (Integer.MAX_VALUE / 2);
            n = random.nextInt(Integer.MAX_VALUE / 2);
            break;
    }

    return new Object[]{a, b, n};
}

