public static Object[] generateValidInput(Random random) {
    int scenario = random.nextInt(10);
    int a, b, c, d;

    switch (scenario) {
        case 0: // All zeros
            a = 0; b = 0; c = 0; d = 0;
            break;
        case 1: // One positive, others zero
            a = random.nextInt(10) + 1;
            b = 0; c = 0; d = 0;
            break;
        case 2: // Mixed positive/negative/zero
            a = random.nextInt(20) - 5;
            b = random.nextInt(20) - 5;
            c = random.nextInt(20) - 5;
            d = random.nextInt(20) - 5;
            break;
        case 3: // All negative
            a = -random.nextInt(10) - 1;
            b = -random.nextInt(10) - 1;
            c = -random.nextInt(10) - 1;
            d = -random.nextInt(10) - 1;
            break;
        case 4: // All positive small
            a = random.nextInt(5) + 1;
            b = random.nextInt(5) + 1;
            c = random.nextInt(5) + 1;
            d = random.nextInt(5) + 1;
            break;
        case 5: // Boundary: -1, 0, 1
            a = random.nextInt(3) - 1;
            b = random.nextInt(3) - 1;
            c = random.nextInt(3) - 1;
            d = random.nextInt(3) - 1;
            break;
        case 6: // Large positives (but safe to avoid OOM)
            a = random.nextInt(100) + 50;
            b = random.nextInt(100) + 50;
            c = random.nextInt(100) + 50;
            d = random.nextInt(100) + 50;
            break;
        case 7: // One large positive, others negative/zero
            a = random.nextInt(200) + 100;
            b = -random.nextInt(10);
            c = 0;
            d = -1;
            break;
        case 8: // Zero and negative mix
            a = 0;
            b = -random.nextInt(10);
            c = random.nextInt(10) + 1;
            d = -random.nextInt(10);
            break;
        case 9: // Random values in range [-50, 100]
            a = random.nextInt(151) - 50;
            b = random.nextInt(151) - 50;
            c = random.nextInt(151) - 50;
            d = random.nextInt(151) - 50;
            break;
        default:
            a = 0; b = 0; c = 0; d = 0;
    }

    return new Object[]{a, b, c, d};
}

