public static Object[] generateValidInput(Random random) {
    int rows;
    int r = random.nextInt(10);
    if (r < 2) {
        rows = 0;
    } else if (r < 4) {
        rows = 1;
    } else {
        rows = 2 + random.nextInt(6);
    }

    int[][] testArray = new int[rows][];

    for (int i = 0; i < rows; i++) {
        int cols;
        int c = random.nextInt(10);
        if (c < 1) {
            cols = 0;
        } else if (c < 3) {
            cols = 1;
        } else if (c < 9) {
            cols = 2;
        } else {
            cols = 3 + random.nextInt(3);
        }

        testArray[i] = new int[cols];

        for (int j = 0; j < cols; j++) {
            int choice = random.nextInt(10);
            if (choice < 2) {
                int[] boundaries = {Integer.MIN_VALUE, Integer.MAX_VALUE, -1, 0, 1};
                testArray[i][j] = boundaries[random.nextInt(boundaries.length)];
            } else {
                testArray[i][j] = random.nextInt(21) - 10;
            }
        }
    }

    if (rows >= 2 && random.nextBoolean()) {
        int[] first = testArray[0];
        int n = first.length;
        int[] reversed = new int[n];
        for (int k = 0; k < n; k++) {
            reversed[k] = first[n - 1 - k];
        }
        testArray[1] = reversed;
    }

    if (rows > 0 && random.nextBoolean()) {
        testArray[random.nextInt(rows)] = new int[0];
    }

    return new Object[]{testArray};
}

