            array = new int[0];
            break;
        case 1:
            // Single element
            array = new int[]{random.nextInt(201) - 100};
            break;
        case 2:
            // Array with all same values
            int val = random.nextInt(201) - 100;
            int len = random.nextInt(10) + 1;
            array = new int[len];
            Arrays.fill(array, val);
            break;
        case 3:
            // Array with max at boundaries and duplicates
            array = new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE, random.nextInt(201) - 100, Integer.MAX_VALUE, Integer.MIN_VALUE};
            break;
        case 4:
            // Array with negative and positive values, max at end
            int n = random.nextInt(10) + 1;
            array = new int[n];
            for (int i = 0; i < n - 1; i++) {
                array[i] = random.nextInt(201) - 100;
            }
            array[n - 1] = Integer.MAX_VALUE;
            break;
        default:
            // Random array with duplicates
            int size = random.nextInt(15) + 1;
            array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = random.nextInt(201) - 100;
            }
            // Insert duplicates randomly
            if (size > 1) {
                int dupIdx = random.nextInt(size);
                array[random.nextInt(size)] = array[dupIdx];
            }
            break;
    }
    return new Object[]{array};
}

