public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(6);
    int[] arr;
    int n;

    switch (choice) {
        case 0:
            // Empty array
            arr = new int[0];
            n = 0;
            break;
        case 1:
            // Single element array
            arr = new int[]{random.nextBoolean() ? 0 : random.nextInt(21) - 10};
            n = 1;
            break;
        case 2:
            // Small array with mixed values (including negative and positive)
            n = random.nextInt(5) + 1;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(21) - 10;
            }
            break;
        case 3:
            // Array with boundary values
            n = random.nextInt(6) + 2;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0) {
                    // Even index: sometimes make it even for sum contribution
                    if (random.nextBoolean()) {
                        arr[i] = 2 * (random.nextInt(10) + 1); // positive even
                    } else {
                        arr[i] = -2 * (random.nextInt(10) + 1); // negative even
                    }
                } else {
                    arr[i] = random.nextInt(21) - 10; // odd index can be anything
                }
            }
            break;
        case 4:
            // Array with extreme values
            n = random.nextInt(5) + 1;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                if (random.nextBoolean()) {
                    arr[i] = Integer.MAX_VALUE;
                } else {
                    arr[i] = Integer.MIN_VALUE;
                }
            }
            break;
        default:
            // Random length and values
            n = random.nextInt(10);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(101) - 50;
            }
            break;
    }

    return new Object[]{arr, n};
}

