import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class IsOctagonal {

    /*@ requires n >= 0 && n <= 26755;
        ensures \result == n * (3 * n - 2);
        assignable \nothing;
      @*/
    public static int isOctagonal(int n) {
        int [] f = new int[n + 1];
        f[0] = 0;
        //@ loop_invariant 0 <= i && i <= n;
        //@ loop_invariant f.length == n + 1;
        //@ loop_invariant f[i] == i * (3 * i - 2);
        //@ decreasing n - i;
        for (int i = 0; i <= n - 1; i++) {
            f[i + 1] = f[i] + 6 * i + 1;
        }
        return f[n];
    }
}

