            }
            return new Object[] { nums };
        case 5: // strictly increasing
            len = random.nextInt(10) + 2;
            nums = new int[len];
            nums[0] = random.nextInt();
            for (int i = 1; i < len; i++) {
                nums[i] = nums[i - 1] + random.nextInt(10) + 1; // ensure positive increase
            }
            return new Object[] { nums };
        case 6: // strictly decreasing
            len = random.nextInt(10) + 2;
            nums = new int[len];
            nums[0] = random.nextInt();
