                } else {
                    nums[i] = random.nextInt();
                }
            }
            return new Object[] { nums };
        case 8: // boundary values: MIN_VALUE, MAX_VALUE, 0, -1, 1
            len = random.nextInt(5) + 2; // 2 to 6
            nums = new int[len];
            int[] boundaryValues = { Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1 };
            for (int i = 0; i < len; i++) {
                nums[i] = boundaryValues[random.nextInt(boundaryValues.length)];
            }
            return new Object[] { nums };
        case 9: // random array of arbitrary length (1 to 20)
            len = random.nextInt(20) + 1; // 1 to 20
            nums = new int[len];
            for (int i = 0; i < len; i++) {
                nums[i] = random.nextInt();
            }
            return new Object[] { nums };
        default:
            // Should never happen, but fallback to empty array
            return new Object[] { new int[0] };
    }
}

