public static Object[] generateValidInput(Random random) {
    // Decide whether to return null array (with some probability)
    if (random.nextInt(10) == 0) {
        return new Object[]{null};
    }

    // Generate random length between 0 and 15 (inclusive)
    int length = random.nextInt(16);
    int[] array = new int[length];

    // Decide the type of array content
    int type = random.nextInt(5);
    if (type == 0) {
        // All positive numbers
        for (int i = 0; i < length; i++) {
            array[i] = random.nextInt(100) + 1; // 1 to 100
        }
    } else if (type == 1) {
        // All negative numbers
        for (int i = 0; i < length; i++) {
            array[i] = -(random.nextInt(100) + 1); // -1 to -100
        }
    } else if (type == 2) {
        // Mixed with zeros
        for (int i = 0; i < length; i++) {
            array[i] = random.nextInt(21) - 10; // -10 to 10
        }
    } else {
        // Random values including extremes
        for (int i = 0; i < length; i++) {
            // Occasionally set to boundary values
            int r = random.nextInt(20);
            if (r == 0) {
                array[i] = Integer.MIN_VALUE;
            } else if (r == 1) {
                array[i] = Integer.MAX_VALUE;
            } else if (r == 2) {
                array[i] = -1;
            } else if (r == 3) {
                array[i] = 0;
            } else if (r == 4) {
                array[i] = 1;
            } else {
                array[i] = random.nextInt(2001) - 1000; // -1000 to 1000
            }
        }
    }

    return new Object[]{array};
}

