public static Object[] generateValidInput(Random random) {
    int n;
    int choice = random.nextInt(8);
    switch (choice) {
        case 0: n = 0; break;
        case 1: n = 1; break;
        case 2: n = 2; break;
        case 3: // power of two
            n = 1 << random.nextInt(31);
            break;
        case 4: // all ones (2^k-1)
            int k = random.nextInt(31);
            n = (1 << k) - 1;
            break;
        case 5: // near max
            n = Integer.MAX_VALUE - random.nextInt(100);
            break;
        case 6: // random positive integer
            n = random.nextInt(Integer.MAX_VALUE);
            break;
        default: // random positive integer
            n = random.nextInt(Integer.MAX_VALUE);
            break;
    }
    return new Object[]{n};
}

