            arr4[0] = new int[0];
            return new Object[]{arr4};
        case 10: // large array with many duplicates and boundary values
            int size3 = random.nextInt(10) + 5;
            int[][] arr5 = new int[size3][2];
            for (int i = 0; i < size3; i++) {
                // first element: 0, 1, -1, MIN, MAX or random
                int firstElem;
                double r = random.nextDouble();
                if (r < 0.2) firstElem = 0;
                else if (r < 0.4) firstElem = 1;
                else if (r < 0.6) firstElem = -1;
                else if (r < 0.7) firstElem = Integer.MIN_VALUE;
                else if (r < 0.8) firstElem = Integer.MAX_VALUE;
                else firstElem = random.nextInt(10) - 5;
                arr5[i][0] = firstElem;
                arr5[i][1] = random.nextInt(100);
            }
            return new Object[]{arr5};
        case 11: // unsorted array with mixed groups
            int size4 = random.nextInt(6) + 2;
            int[][] arr6 = new int[size4][2];
            // generate some random first elements, possibly duplicates
            for (int i = 0; i < size4; i++) {
