public static Object[] generateValidInput(Random random) {
    // The method accepts a single int parameter n.
    // We need to cover valid inputs: n >= 0 (since the algorithm uses dp array of size n+1).
    // Edge cases: 0, 1, small numbers, perfect squares, non-perfect squares, and large values up to a safe bound.

    int n;
    int choice = random.nextInt(5);

    switch (choice) {
        case 0:
            n = 0;
            break;
        case 1:
            n = 1;
            break;
        case 2:
            // Perfect square
            int sqrt = random.nextInt(100) + 1; // 1 to 100
            n = sqrt * sqrt;
            break;
        case 3:
            // Non-perfect small number (2 to 100)
            n = random.nextInt(99) + 2; // 2 to 100
            break;
        default:
            // Large number but safe to avoid memory issues (e.g., up to 10000)
            n = random.nextInt(10000) + 1; // 1 to 10000
            break;
    }

    // Ensure n is non-negative as required by the algorithm.
    // (We do not test negative n because the method would throw an exception for n < 0.)

    return new Object[]{n};
}

