class GetMinSquares {

    /*@ public normal_behavior
      @   requires n >= 1;
      @   assignable \nothing;
      @   ensures \result >= 1 && \result <= 4;
      @   ensures \result <= n;
      @   ensures n == 1 ==> \result == 1;
      @*/
    public static int getMinSquares(int n) {
        int[] dp = new int[n + 1];
        dp[0] = 0;
        dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
            for (int j = 1; j * j <= i; j++) {
                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            }
        }
        return dp[n];
    }
}

