        m = 0;
        n = length - 1;
    } else if (choice == 1 && length > 1) {
        // Test with m = 0 and n = 0 (single element at start)
        m = 0;
        n = 0;
    } else if (choice == 2 && length > 1) {
        // Test with m = length - 1 and n = length - 1 (single element at end)
        m = length - 1;
        n = length - 1;
    } else if (choice == 3 && length > 2) {
        // Test with m = 1 and n = length - 2 (middle range)
        m = 1;
        n = length - 2;
    }

    // Occasionally test with large values
    if (random.nextBoolean()) {
        for (int i = 0; i < length; i++) {
