public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    int[] arr;

    switch (choice) {
        case 0:
            arr = new int[0];
            break;
        case 1:
            arr = new int[]{0};
            break;
        case 2:
            arr = new int[]{random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE};
            break;
        case 3: {
            int len = 2 + random.nextInt(10);
            int start = random.nextInt(21) - 10;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = start + i;
            }
            break;
        }
        case 4: {
            int len = 2 + random.nextInt(10);
            int start = random.nextInt(21) - 10;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = start - i;
            }
            break;
        }
        case 5: {
            int len = random.nextInt(16);
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = random.nextInt();
            }
            break;
        }
        case 6:
            arr = new int[]{Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1, 0, Integer.MIN_VALUE, Integer.MAX_VALUE};
            break;
        case 7: {
            int len = 2 + random.nextInt(8);
            int peak = random.nextInt(len);
            int val = random.nextInt(11) - 5;
            arr = new int[len];
            for (int i = 0; i <= peak; i++) {
                arr[i] = val + i;
            }
            val = arr[peak] - 1;
            for (int i = peak + 1; i < len; i++) {
                arr[i] = val;
                val--;
            }
            break;
        }
        case 8:
            arr = new int[]{5, 5, 5, 5, 5};
            break;
        default:
            arr = null;
            break;
    }

    return new Object[]{arr};
}

