    int uniformValue = 0;
    if (uniformBoundary && cols > 0) {
        switch (random.nextInt(4)) {
            case 0: uniformValue = Integer.MIN_VALUE; break;
            case 1: uniformValue = Integer.MAX_VALUE; break;
            case 2: uniformValue = 1; break;
            default: uniformValue = -1; break;
        }
    }

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (uniformBoundary) {
                nums[r][c] = uniformValue;
            } else {
                int choice = random.nextInt(10);
                switch (choice) {
                    case 0: nums[r][c] = Integer.MIN_VALUE; break;
                    case 1: nums[r][c] = Integer.MAX_VALUE; break;
