public static Object[] generateValidInput(Random random) {
    int x;
    int y;

    int xChoice = random.nextInt(7);
    switch (xChoice) {
        case 0: x = 0; break;
        case 1: x = 1; break;
        case 2: x = -1; break;
        case 3: x = Integer.MAX_VALUE; break;
        case 4: x = Integer.MIN_VALUE; break;
        default: x = random.nextInt(201) - 100; // -100..100
    }

    int yChoice = random.nextInt(7);
    switch (yChoice) {
        case 0: y = 0; break;
        case 1: y = 1; break;
        case 2: y = -1; break;
        case 3: y = Integer.MIN_VALUE; break;
        case 4: y = random.nextInt(100) + 1; // 1..100
        case 5: y = -(random.nextInt(100) + 1); // -100..-1
        default: y = random.nextInt(201) - 100; // -100..100
    }

    return new Object[]{x, y};
}

