                    break;
                case 4:
                    testArray[i][j] = Integer.MIN_VALUE;
                    break;
                default:
                    testArray[i][j] = random.nextInt(2001) - 1000;
            }
        }
    }

    // Add edge case: single row
    if (random.nextBoolean()) {
        testArray = new int[1][cols];
        for (int j = 0; j < cols; j++) {
            testArray[0][j] = random.nextInt(2001) - 1000;
        }
    }

