    if (random.nextBoolean()) {
        testArray = new int[rows][1];
        n = 0;
        for (int i = 0; i < rows; i++) {
            testArray[i][0] = random.nextInt(2001) - 1000;
        }
    }

    return new Object[]{testArray, n};
}

