public static Object[] generateValidInput(Random random) {
    // Generate random string length between 0 and 30
    int length = random.nextInt(31);
    StringBuilder sb = new StringBuilder();

    // Character set: uppercase letters and spaces (similar to examples)
    String chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";

    // Generate random string
    for (int i = 0; i < length; i++) {
        sb.append(chars.charAt(random.nextInt(chars.length())));
    }

    // Special cases
    int caseType = random.nextInt(5);
    String input;

    switch (caseType) {
        case 0: // Empty string
            input = "";
            break;
        case 1: // Single character
            input = String.valueOf((char)('A' + random.nextInt(26)));
            break;
        case 2: // Palindrome string
            String half = generateRandomAlphabeticString(random, random.nextInt(10));
            input = half + new StringBuilder(half).reverse().toString();
            break;
        case 3: // All same characters
            char c = (char)('A' + random.nextInt(26));
            input = String.valueOf(c).repeat(random.nextInt(20));
            break;
        default: // Random string
            input = sb.toString();
            break;
    }

    return new Object[]{input};
}

private static String generateRandomAlphabeticString(Random random, int length) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        sb.append((char)('A' + random.nextInt(26)));
    }
    return sb.toString();
}

