      @ requires x > 0 && y > 0;
      @ assignable \nothing;
      @ ensures (x == 1 || y == 1) ==> !\result.booleanValue();
      @ ensures (x > 1 && y > 1 && x == y) ==> \result.booleanValue();
      @ ensures (x > 1 && y > 1 && x != y) ==> (
      @   \result.booleanValue() <==> (\forall int i; 2 <= i && i <= (x < y ? y : x) / 2; !(x % i == 0 && y % i == 0))
      @ );
      @*/
    public static Boolean isCoprime(int x, int y) {
