        /*@ loop_invariant 2 <= i && i <= y / 2 + 1;
          @ loop_invariant (\forall int k; 2 <= k && k < i; !(x % k == 0 && y % k == 0));
          @ decreases y / 2 + 1 - i;
          @*/
        for (int i = 2; i <= y / 2; i++) {
            if (x % i == 0 && y % i == 0) {
                return false;
            }
        }
