public static Object[] generateValidInput(Random random) {
    int scenario = random.nextInt(8);
    int[] arr1, arr2;

    switch (scenario) {
        case 0: // both arrays empty
            arr1 = new int[0];
            arr2 = new int[0];
            break;
        case 1: // first array empty, second non-empty
            arr1 = new int[0];
            arr2 = generateRandomArray(random, 1 + random.nextInt(4));
            break;
        case 2: // second array empty, first non-empty
            arr1 = generateRandomArray(random, 1 + random.nextInt(4));
            arr2 = new int[0];
            break;
        case 3: // both arrays with overlapping elements
            int size = 1 + random.nextInt(3);
            arr1 = generateRandomArray(random, size);
            arr2 = new int[size];
            // copy some elements from arr1 to arr2 to create overlap
            for (int i = 0; i < size; i++) {
                if (random.nextBoolean()) {
                    arr2[i] = arr1[i];
                } else {
                    arr2[i] = random.nextInt();
                }
            }
            break;
        case 4: // both arrays with no overlap
            arr1 = generateRandomArray(random, 1 + random.nextInt(3));
            arr2 = new int[arr1.length];
            // ensure elements are different from arr1
            for (int i = 0; i < arr2.length; i++) {
                int val;
                do {
                    val = random.nextInt();
                } while (contains(arr1, val));
                arr2[i] = val;
            }
            break;
        case 5: // one array null
            if (random.nextBoolean()) {
                arr1 = null;
                arr2 = generateRandomArray(random, 1 + random.nextInt(4));
            } else {
                arr1 = generateRandomArray(random, 1 + random.nextInt(4));
                arr2 = null;
            }
            break;
        case 6: // both arrays with single element
            arr1 = new int[]{random.nextInt()};
            arr2 = new int[]{random.nextInt()};
            break;
        case 7: // boundary values in arrays
            int[] boundaries = {Integer.MIN_VALUE, Integer.MAX_VALUE, 0, -1, 1};
            int size1 = random.nextInt(5) + 1;
            int size2 = random.nextInt(5) + 1;
            arr1 = new int[size1];
            arr2 = new int[size2];
            for (int i = 0; i < size1; i++) {
                arr1[i] = boundaries[random.nextInt(boundaries.length)];
            }
            for (int i = 0; i < size2; i++) {
                arr2[i] = boundaries[random.nextInt(boundaries.length)];
            }
            break;
        default:
            arr1 = generateRandomArray(random, random.nextInt(5));
            arr2 = generateRandomArray(random, random.nextInt(5));
            break;
    }

    return new Object[]{arr1, arr2};
}

private static int[] generateRandomArray(Random random, int size) {
    int[] arr = new int[size];
    for (int i = 0; i < size; i++) {
        arr[i] = random.nextInt();
    }
    return arr;
}

private static boolean contains(int[] arr, int val) {
    for (int x : arr) {
        if (x == val) return true;
    }
    return false;
}

