            Arrays.fill(nums, val);
            break;
        case 3: // increasing sequence
            len = random.nextInt(5) + 2;
            nums = new int[len];
            nums[0] = random.nextInt(100) - 50;
            for (int i = 1; i < len; i++) {
                nums[i] = nums[i-1] + random.nextInt(10) + 1;
            }
            break;
        case 4: // decreasing sequence
            len = random.nextInt(5) + 2;
            nums = new int[len];
            nums[0] = random.nextInt(100) + 50;
            for (int i = 1; i < len; i++) {
                nums[i] = nums[i-1] - random.nextInt(10) - 1;
            }
            break;
        case 5: // include extreme values
            len = random.nextInt(5) + 2;
            nums = new int[len];
            nums[0] = Integer.MAX_VALUE;
