import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class CountNum {

    /*@
      @ public normal_behavior
      @   requires n >= 0;
      @   ensures \result == (n == 0 ? 0 : (n & 1) + popcount(n >>> 1));
      @   assignable \nothing;
      @*/
    public /*@ pure @*/ static int popcount(int n) {
        if (n == 0) {
            return 0;
        }
        return (n & 1) + popcount(n >>> 1);
    }

    /*@
      @ public normal_behavior
      @   requires n >= 0;
      @   ensures \result == popcount(\old(n));
      @   assignable \nothing;
      @*/
    public static int countNum(int n) {
        int count = 0;
        //@ ghost int orig;
        //@ set orig = n;
        //@ maintaining n >= 0 && count >= 0 && count == popcount(orig) - popcount(n);
        //@ decreases n;
        while (n > 0) {
            if ((n & 1) == 1) {
                count++;
            }
            n = n >> 1;
        }
        return count;
    }
}

