    } else if (choice < 4) {
        // Single character
        char c = (char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26));
        input = String.valueOf(c);
    } else if (choice < 6) {
        // Two characters
        char c1 = (char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26));
        char c2 = (char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26));
        input = "" + c1 + c2;
    } else if (choice < 7) {
        // Null
        input = null;
    } else if (choice < 8) {
        // String with spaces
        int len = random.nextInt(5) + 3;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            if (random.nextBoolean()) {
                sb.append(' ');
            } else {
                sb.append((char) (random.nextBoolean() ? 'a' + random.nextInt(26) : 'A' + random.nextInt(26)));
            }
        }
        input = sb.toString();
    } else {
        // Random string of length 0 to 15
        int len = random.nextInt(16);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            // Mix of letters, digits, and special characters
            int type = random.nextInt(3);
            char c;
            switch (type) {
                case 0: c = (char) ('a' + random.nextInt(26)); break;
                case 1: c = (char) ('A' + random.nextInt(26)); break;
                case 2: c = (char) ('0' + random.nextInt(10)); break;
                default: c = ' ';
            }
            sb.append(c);
        }
        input = sb.toString();
    }
    return new Object[]{input};
}

