public static Object[] generateValidInput(Random random) {
    int caseType = random.nextInt(10); // 0-9

    int[] nums1;
    int[] nums2;

    if (caseType < 2) {
        // Null cases
        nums1 = null;
        nums2 = random.nextBoolean() ? null : generateRandomArray(random);
    } else if (caseType < 4) {
        // Empty array cases
        nums1 = new int[0];
        nums2 = random.nextBoolean() ? new int[0] : generateRandomArray(random);
    } else {
        // Normal random arrays (possibly of different lengths)
        int len1 = random.nextInt(11); // 0-10
        int len2 = random.nextInt(11); // 0-10
        nums1 = generateRandomArray(random, len1);
        nums2 = generateRandomArray(random, len2);
    }

    return new Object[]{nums1, nums2};
}

// Helper method to generate a random array with a given length
private static int[] generateRandomArray(Random random, int length) {
    int[] arr = new int[length];
    for (int i = 0; i < length; i++) {
        int choice = random.nextInt(10);
        if (choice < 2) {
            arr[i] = 0;
        } else if (choice < 4) {
            arr[i] = 1;
        } else if (choice < 6) {
            arr[i] = -1;
        } else if (choice < 8) {
            arr[i] = random.nextInt(100) - 50; // small range
        } else {
            arr[i] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        }
    }
    return arr;
}

// Helper method to generate a random array with random length
private static int[] generateRandomArray(Random random) {
    int len = random.nextInt(11); // 0-10
    return generateRandomArray(random, len);
}

