        default: // Normal random array
            n = random.nextInt(20) + 1;
            arr = new int[n];
            boolean useExtremes = random.nextBoolean();
            for (int i = 0; i < n; i++) {
                if (useExtremes && i == 0) {
                    arr[i] = Integer.MIN_VALUE;
                } else if (useExtremes && i == n - 1) {
                    arr[i] = Integer.MAX_VALUE;
                } else {
                    arr[i] = random.nextInt(2001) - 1000;
                }
            }
            break;
    }

    return new Object[]{arr, n};
}

