        case 0: // Null arrays
            return new Object[]{null, 0, null, 0};
        case 1: // Empty arrays
            return new Object[]{new int[]{}, 0, new int[]{}, 0};
        case 2: // Equal arrays
            m = random.nextInt(10);
            arr1 = new int[m];
            arr2 = new int[m];
            for (int i = 0; i < m; i++) {
                int val = random.nextInt(100);
                arr1[i] = val;
                arr2[i] = val;
            }
            return new Object[]{arr1, m, arr2, m};
        case 3: // Subset case
            m = random.nextInt(10) + 1;
            n = random.nextInt(m) + 1;
            arr1 = new int[m];
            HashSet<Integer> used = new HashSet<>();
            for (int i = 0; i < m; i++) {
                int val = random.nextInt(100);
                while (used.contains(val)) {
                    val = random.nextInt(100);
                }
                used.add(val);
                arr1[i] = val;
            }
            // Pick n elements from arr1 to be subset
            arr2 = new int[n];
            for (int i = 0; i < n; i++) {
                arr2[i] = arr1[random.nextInt(m)];
            }
            return new Object[]{arr1, m, arr2, n};
        case 4: // Not subset case (random)
            m = random.nextInt(10) + 1;
            n = random.nextInt(10) + 1;
            arr1 = new int[m];
            arr2 = new int[n];
            for (int i = 0; i < m; i++) {
