            return new Object[]{arr1, m, arr2, n};
        default: // Boundary values
            m = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            n = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            arr1 = new int[Math.min(Math.abs(m), 10)];
            arr2 = new int[Math.min(Math.abs(n), 10)];
            for (int i = 0; i < arr1.length; i++) {
                arr1[i] = random.nextInt(200) - 100;
            }
            for (int i = 0; i < arr2.length; i++) {
                arr2[i] = random.nextInt(200) - 100;
            }
            return new Object[]{arr1, m, arr2, n};
    }
