      @   requires 0 <= n && n <= arr2.length;
      @   ensures \result == (\forall int i; 0 <= i && i < n; 
      @                          (\exists int j; 0 <= j && j < m; arr1[j] == arr2[i]));
      @*/
    public static Boolean isSubset(int[] arr1, int m, int[] arr2, int n) {
        HashSet<Integer> set = new HashSet<>();
        for (int i = 0; i < m; i++) {
            set.add(arr1[i]);
        }
