public static Object[] generateValidInput(Random random) {
    String[] fixedCases = {
        "",
        " ",
        "   ",
        "a",
        "a a",
        "a b c",
        "a a a",
        "Python Exercises Practice Solution Exercises",
        "Python Exercises Practice Solution Python",
        "Python Exercises Practice Solution Practice",
        "hello world hello",
        "foo bar foo baz foo",
        "  leading spaces",
        "trailing spaces  ",
        "multiple   spaces between",
        "case Case CASE case",
        "one two three four",
        "same same same same"
    };

    int mode = random.nextInt(3);
    if (mode == 0) {
        return new Object[]{fixedCases[random.nextInt(fixedCases.length)]};
    } else if (mode == 1) {
        String[] vocab = {"a", "b", "c", "Python", "Exercises", "Practice", "Solution", "hello", "world", "foo", "bar", "baz", "test", "TEST", "Test", "123"};
        int groups = random.nextInt(6) + 1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < groups; i++) {
            if (i > 0) {
                int spaces = 1 + random.nextInt(3);
                for (int j = 0; j < spaces; j++) {
                    sb.append(' ');
                }
            }
            String word = vocab[random.nextInt(vocab.length)];
            int repeat = 1;
            if (random.nextBoolean()) {
                repeat = 2 + random.nextInt(3);
            }
            for (int j = 0; j < repeat; j++) {
                if (j > 0) {
                    sb.append(' ');
                }
                sb.append(word);
            }
        }
        if (random.nextBoolean()) {
            sb.insert(0, ' ');
        }
        if (random.nextBoolean()) {
            sb.append(' ');
        }
        return new Object[]{sb.toString()};
    } else {
        String[] singleWords = {"", "a", "word", "test", "Python", "123", "x", "   "};
        return new Object[]{singleWords[random.nextInt(singleWords.length)]};
    }
}

