public static Object[] generateValidInput(Random random) {
    // Randomly choose array length between 0 and 10 (inclusive), with occasional larger sizes
    int n;
    int choice = random.nextInt(5);
    if (choice == 0) {
        n = 0; // empty array
    } else if (choice == 1) {
        n = 1; // minimal non-empty
    } else if (choice == 2) {
        n = 2; // small
    } else if (choice == 3) {
        n = 3 + random.nextInt(8); // 3-10
    } else {
        n = 10 + random.nextInt(20); // 10-29 for larger
    }

    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        // Only 0, 1, 2 allowed
        arr[i] = random.nextInt(3);
    }

    // Occasionally force specific patterns:
    int pattern = random.nextInt(5);
    if (pattern == 0) {
        // All zeros
        for (int i = 0; i < n; i++) arr[i] = 0;
    } else if (pattern == 1) {
        // All ones
        for (int i = 0; i < n; i++) arr[i] = 1;
    } else if (pattern == 2) {
        // All twos
        for (int i = 0; i < n; i++) arr[i] = 2;
    } else if (pattern == 3) {
        // Already sorted
        for (int i = 0; i < n; i++) {
            // Random sorted sequence
            if (n > 0) {
                int split1 = random.nextInt(n + 1);
                int split2 = random.nextInt(n - split1 + 1) + split1;
                for (int j = 0; j < n; j++) {
                    if (j < split1) arr[j] = 0;
                    else if (j < split2) arr[j] = 1;
                    else arr[j] = 2;
                }
            }
        }
    } // else keep random

    // Return parameters: arr (int[]), n (int)
    return new Object[]{arr, n};
}

