import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class GetTotalNumberOfSequences {

    //@ requires m >= 0 && n >= 0;
    //@ requires m <= 200 && n <= 50;
    //@ assignable \nothing;
    //@ ensures \result >= 0;
    //@ ensures (m == 0 || n == 0 || m < n) ==> \result == 0;
    //@ ensures (m > 0 && n == 1) ==> \result == m;
    public static int getTotalNumberOfSequences(int m, int n) {
        int[][] T = new int[m+1][n+1];
        //@ maintaining 0 <= i && i <= m + 1;
        //@ decreasing m + 1 - i;
        for (int i = 0; i < m+1; i++) {
            //@ maintaining 0 <= j && j <= n + 1;
            //@ decreasing n + 1 - j;
            for (int j = 0; j < n+1; j++) {
                if (i == 0 || j == 0) {
                    T[i][j] = 0;
                } else if (i < j) {
                    T[i][j] = 0;
                } else if (j == 1) {
                    T[i][j] = i;
                } else {
                    T[i][j] = T[i-1][j] + T[i/2][j-1];
                }
            }
        }
        return T[m][n];
    }
}

