        default: // Boundary values
            n = random.nextBoolean() ? 1 : random.nextInt(200) + 1;
            x = random.nextBoolean() ? 1 : random.nextInt(50) + 1;
            y = random.nextBoolean() ? 0 : random.nextInt(x);
            break;
    }
    if (n < 1) n = 1;
    if (x < 1) x = 1;
    if (y < 0) y = 0;
    if (y >= x) y = x - 1;
    return new Object[]{n, x, y};
}

