import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class FindMaxVal {

    /*@ public normal_behavior
      @ requires n >= 0 && n < Integer.MAX_VALUE;
      @ requires x > 0;
      @ requires 0 <= y && y < x;
      @ assignable \nothing;
      @ ensures 0 <= \result && \result <= n;
      @ ensures \result == 0 || (1 <= \result && \result <= n && \result % x == y);
      @ ensures (\forall int k; 1 <= k && k <= n && k % x == y; k <= \result);
      @*/
    public static int findMaxVal(int n, int x, int y) {
        int max = 0;

        /*@ loop_invariant 1 <= i && i <= n + 1;
          @ loop_invariant 0 <= max && max < i && max <= n;
          @ loop_invariant max == 0 || (max % x == y);
          @ loop_invariant (\forall int j; 1 <= j && j < i && j % x == y; j <= max);
          @ decreases n + 1 - i;
          @*/
        for (int i = 1; i <= n; i++) {
            if ((i % x) == y) {
                max = i;
            }
        }
        return max;
    }
}

