public static Object[] generateValidInput(Random random) {
    String input;
    int type = random.nextInt(5);
    switch (type) {
        case 0:
            // Empty string
            input = "";
            break;
        case 1:
            // Single character
            input = String.valueOf((char) ('a' + random.nextInt(26)));
            break;
        case 2:
            // Single word with spaces around
            input = "   " + generateRandomWord(random) + "   ";
            break;
        case 3:
            // Multiple words with varying spaces
            int wordCount = random.nextInt(5) + 1;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < wordCount; i++) {
                if (i > 0) {
                    sb.append(" ".repeat(random.nextInt(4)));
                }
                sb.append(generateRandomWord(random));
            }
            input = sb.toString();
            break;
        default:
            // Random string with spaces and special characters
            int length = random.nextInt(20);
            StringBuilder sb2 = new StringBuilder();
            for (int i = 0; i < length; i++) {
                if (random.nextBoolean()) {
                    sb2.append(' ');
                } else {
                    sb2.append((char) ('a' + random.nextInt(26)));
                }
            }
            input = sb2.toString();
            break;
    }
    return new Object[]{input};
}

private static String generateRandomWord(Random random) {
    int wordLength = random.nextInt(10) + 1;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < wordLength; i++) {
        sb.append((char) ('a' + random.nextInt(26)));
    }
    return sb.toString();
}

