public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    int number;
    switch (choice) {
        case 0:
            number = 0;
            break;
        case 1:
            number = 1;
            break;
        case 2:
            number = -1;
            break;
        case 3:
            number = Integer.MAX_VALUE;
            break;
        case 4:
            number = Integer.MIN_VALUE;
            break;
        case 5:
            int[] knownArmstrong = {153, 370, 371, 407};
            number = knownArmstrong[random.nextInt(knownArmstrong.length)];
            break;
        case 6:
            number = 2 + random.nextInt(1000);
            break;
        case 7:
            number = 1000 + random.nextInt(9000);
            break;
        case 8:
            number = random.nextInt(10000);
            break;
        default:
            number = random.nextInt();
            break;
    }
    return new Object[]{number};
}

