class GetFirstSetBitPos {

    /*@ requires n > 0;
      @ ensures 1 <= \result && \result <= 31;
      @ ensures (\old(n) & (1 << (\result - 1))) != 0;
      @ ensures (\forall int k; 1 <= k && k < \result; (\old(n) & (1 << (k - 1))) == 0);
      @*/
    public static int getFirstSetBitPos(int n) {
        int i = 1;
        /*@ loop_invariant
              n > 0 &&
              1 <= i && i <= 31 &&
              n == (\old(n) >> (i - 1)) &&
              (\forall int k; 1 <= k && k < i; (\old(n) & (1 << (k - 1))) == 0);
