public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    int[] numbers;
    switch (choice) {
        case 0:
            // Empty array (edge case: division by zero in return)
            numbers = new int[]{};
            break;
        case 1:
            // Single element array
            numbers = new int[]{random.nextBoolean() ? 1 : -1};
            break;
        case 2:
            // All zeros
            numbers = new int[]{0, 0, 0};
            break;
        case 3:
            // Contains zero
            numbers = new int[]{random.nextInt(10) + 1, 0, random.nextInt(10) + 1};
            break;
        case 4:
            // Mixed positive and negative
            numbers = new int[]{random.nextInt(10) + 1, -(random.nextInt(10) + 1), random.nextInt(10) + 1};
            break;
        case 5:
            // All negative
            numbers = new int[]{-(random.nextInt(10) + 1), -(random.nextInt(10) + 1), -(random.nextInt(10) + 1)};
            break;
        case 6:
            // Large values
            numbers = new int[]{Integer.MAX_VALUE, Integer.MAX_VALUE};
            break;
        case 7:
            // Very small values
            numbers = new int[]{Integer.MIN_VALUE, Integer.MIN_VALUE};
            break;
        case 8:
            // Mixed large and small
            numbers = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE};
            break;
        default:
            // Random array of length 1-10 with values -5 to 5
            int len = random.nextInt(10) + 1;
            numbers = new int[len];
            for (int i = 0; i < len; i++) {
                numbers[i] = random.nextInt(11) - 5;
            }
            break;
    }
    return new Object[]{numbers};
}

