public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    String text;
    int n;

    switch (choice) {
        case 0:
            // Normal case with mixed special characters
            text = "Python language, Programming language.";
            n = random.nextInt(5) + 1;
            break;
        case 1:
            // Normal case with multiple spaces
            text = "a b c,d e f";
            n = random.nextInt(5) + 1;
            break;
        case 2:
            // Normal case with only one replacement
            text = "ram reshma,ram rahim";
            n = 1;
            break;
        case 3:
            // Boundary: n = 0, no replacements
            text = random.nextBoolean() ? "hello world, test." : "";
            n = 0;
            break;
        case 4:
            // Boundary: n = 1
            text = random.nextBoolean() ? "a b c" : "single";
            n = 1;
            break;
        case 5:
            // Boundary: n = -1 (negative, should replace nothing)
            text = "test, string. with spaces";
            n = -1;
            break;
        case 6:
            // Boundary: n = Integer.MAX_VALUE
            text = "a,b.c d";
            n = Integer.MAX_VALUE;
            break;
        case 7:
            // Boundary: n = Integer.MIN_VALUE
            text = "x y,z.w";
            n = Integer.MIN_VALUE;
            break;
        case 8:
            // Edge: null text
            text = null;
            n = random.nextInt(10);
            break;
        case 9:
            // Edge: empty string with various n
            text = "";
            n = random.nextInt(3) == 0 ? 0 : (random.nextInt(3) == 1 ? 1 : random.nextInt(10));
            break;
        default:
            // Random text with random n
            int length = random.nextInt(20);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < length; i++) {
                int charType = random.nextInt(4);
                if (charType == 0) {
                    sb.append(' ');
                } else if (charType == 1) {
                    sb.append(',');
                } else if (charType == 2) {
                    sb.append('.');
                } else {
                    sb.append((char)('a' + random.nextInt(26)));
                }
            }
            text = sb.toString();
            n = random.nextInt(10);
            break;
    }

    return new Object[]{text, n};
}

