public static Object[] generateValidInput(Random random) {
    int n;
    int[] arr;
    int sum;
    int choice = random.nextInt(5);
    switch (choice) {
        case 0:
            // Empty array
            n = 0;
            arr = new int[0];
            sum = random.nextInt(21) - 10;
            break;
        case 1:
            // Small array with random values including negatives
            n = 1 + random.nextInt(5);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(11) - 5;
            }
            sum = random.nextInt(21) - 10;
            break;
        case 2:
            // Array with all same values
            n = 1 + random.nextInt(5);
            int val = random.nextInt(11) - 5;
            arr = new int[n];
            Arrays.fill(arr, val);
            sum = val * 2;
            break;
        case 3:
            // Boundary: extreme values
            n = 1 + random.nextInt(5);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = (i % 2 == 0) ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }
            sum = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            break;
        default:
            // Normal random case with larger n
            n = 1 + random.nextInt(10);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(2001) - 1000;
            }
            sum = random.nextInt(2001) - 1000;
            break;
    }
    return new Object[]{arr, n, sum};
}

