class GetPairsCount {

    /*@ public normal_behavior
      @ requires arr != null;
      @ requires n >= 0 && n <= arr.length;
      @ requires \forall int i; 0 <= i && i < n; \forall int j; i < j && j < n; (long)arr[i] + (long)arr[j] >= Integer.MIN_VALUE && (long)arr[i] + (long)arr[j] <= Integer.MAX_VALUE;
      @ assignable \nothing;
      @ ensures \result == countPairsFrom(arr, n, n, sum);
      @*/
    public static int getPairsCount(int[] arr, int n, int sum) {
        int count = 0;
        /*@ loop_invariant 0 <= i && i <= n;
          @ loop_invariant count == countPairsFrom(arr, i, n, sum);
          @ decreases n - i;
          @*/
        for (int i = 0; i < n; i++) {
            /*@ loop_invariant i+1 <= j && j <= n;
              @ loop_invariant count == countPairsFrom(arr, i, n, sum) + countPairsWithFirst(arr, i, j, sum);
              @ decreases n - j;
              @*/
            for (int j = i + 1; j < n; j++) {
                if (arr[i] + arr[j] == sum) {
                    count++;
                }
            }
        }
        return count;
    }

    /*@ public normal_behavior
      @ requires arr != null;
      @ requires 0 <= i && i <= n && n <= arr.length;
      @ requires \forall int a; 0 <= a && a < i; \forall int k; a < k && k < n; (long)arr[a] + (long)arr[k] >= Integer.MIN_VALUE && (long)arr[a] + (long)arr[k] <= Integer.MAX_VALUE;
      @ assignable \nothing;
      @ ensures \result == (i <= 0 ? 0 : countPairsFrom(arr, i-1, n, sum) + countPairsWithFirst(arr, i-1, n, sum));
      @ measured_by i;
      @*/
    /*@ pure @*/
    public static int countPairsFrom(int[] arr, int i, int n, int sum) {
        if (i <= 0) {
            return 0;
        }
        return countPairsFrom(arr, i-1, n, sum) + countPairsWithFirst(arr, i-1, n, sum);
    }

    /*@ public normal_behavior
      @ requires arr != null;
      @ requires 0 <= a && a < n && n <= arr.length;
      @ requires \forall int k; a < k && k < n; (long)arr[a] + (long)arr[k] >= Integer.MIN_VALUE && (long)arr[a] + (long)arr[k] <= Integer.MAX_VALUE;
      @ assignable \nothing;
      @ ensures \result == (a+1 >= n ? 0 : countPairsWithFirst(arr, a, n-1, sum) + (arr[a] + arr[n-1] == sum ? 1 : 0));
      @ measured_by n - a;
      @*/
    /*@ pure @*/
    public static int countPairsWithFirst(int[] arr, int a, int n, int sum) {
        if (a+1 >= n) {
            return 0;
        }
        return countPairsWithFirst(arr, a, n-1, sum) + (arr[a] + arr[n-1] == sum ? 1 : 0);
    }
}

