public static Object[] generateValidInput(Random random) {
    List<Object> input = new ArrayList<>();

    // Empty list: instanceof List true, size > 0 false
    input.add(new ArrayList<Object>());

    // Non-empty list: instanceof List true, size > 0 true
    List<Object> nonEmptyList = new ArrayList<>();
    nonEmptyList.add("a");
    nonEmptyList.add("b");
    input.add(nonEmptyList);

    // Empty string: instanceof String true, isEmpty() true
    input.add("");

    // Non-empty string: instanceof String true, isEmpty() false
    input.add("str" + random.nextInt(100));

    // Non-list, non-string object: instanceof List false, instanceof String false
    input.add(random.nextInt(1000));

    return new Object[]{input};
}

