        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            sb.append(characters.charAt(random.nextInt(characters.length())));
        }
        return new Object[]{sb.toString()};
    }

    if (mode == 5) {
        int len = random.nextInt(21);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++) {
            sb.append(random.nextBoolean() ? '0' : '1');
