import java.util.*;
import java.math.*;

class CountRotation {

    /*@ requires arr != null;
      @ requires 0 <= n && n <= arr.length;
      @ requires n <= Integer.MAX_VALUE / 2; // Prevents overflow in mid calculation
      @ assignable \nothing;
      @ ensures n == 0 ==> \result == 0;
      @ ensures n > 0 ==> 1 <= \result && \result <= n;
      @*/
    public static int countRotation(int[] arr, int n) {
        if (n == 0) {
            return 0;
        }
        int left = 0, right = n - 1;
        /*@ loop_invariant 0 <= left && left <= right && right < n;
          @ decreases right - left;
          @*/
        while (left < right) {
            if (arr[left] < arr[right]) {
                return left + 1;
