            length = random.nextInt(10);
            break;
        case 4:
            length = random.nextInt(20);
            break;
        default:
            length = random.nextInt(10);
    }

    int[] arr = new int[length];
    for (int i = 0; i < length; i++) {
        int valueChoice = random.nextInt(6);
        switch (valueChoice) {
            case 0:
                arr[i] = 0;
                break;
            case 1:
                arr[i] = 1;
                break;
            case 2:
                arr[i] = -1;
                break;
            case 3:
                arr[i] = Integer.MAX_VALUE;
                break;
            case 4:
                arr[i] = Integer.MIN_VALUE;
                break;
            default:
                arr[i] = random.nextInt(200) - 100;
        }
    }

