    // Generate array size: include edge cases 0, 1, and random sizes
    int arraySize;
    int sizeChoice = random.nextInt(3);
    if (sizeChoice == 0) {
        arraySize = 0; // empty array
    } else if (sizeChoice == 1) {
        arraySize = 1; // single element
    } else {
        arraySize = random.nextInt(10) + 2; // random size 2-11
    }

    int[] testTup = new int[arraySize];
    for (int i = 0; i < arraySize; i++) {
        // Include boundary values and random values
