        if (valueChoice == 0) {
            testTup[i] = 0; // boundary
        } else if (valueChoice == 1) {
            testTup[i] = -1; // negative boundary
        } else if (valueChoice == 2) {
            testTup[i] = Integer.MAX_VALUE; // max value
        } else if (valueChoice == 3) {
            testTup[i] = Integer.MIN_VALUE; // min value
        } else {
            testTup[i] = random.nextInt(2001) - 1000; // random -1000 to 1000
        }
    }

    // Generate string: include empty string, null, and random strings
    String k;
    int stringChoice = random.nextInt(3);
    if (stringChoice == 0) {
        k = ""; // empty string
    } else if (stringChoice == 1) {
        k = null; // null string
