public static Object[] generateValidInput(Random random) {
    // Generate a random text string
    String[] sampleTexts = {
        "The quick brown fox jumps over the lazy dog.",
        "hello world",
        "test string with special chars: !@#$%^&*()",
        "12345",
        "",
        "a",
        "   spaces around   ",
        "multi\nline\ntext",
        "unicode: \u00e9\u00e8\u00ea",
        "pattern inside: abc123xyz"
    };
    String text = sampleTexts[random.nextInt(sampleTexts.length)];

    // Occasionally use very long text
    if (random.nextBoolean()) {
        StringBuilder sb = new StringBuilder();
        int length = 100 + random.nextInt(500);
        for (int i = 0; i < length; i++) {
            sb.append((char)('a' + random.nextInt(26)));
        }
        text = sb.toString();
    }

    // Generate patterns array
    int patternCount;
    if (random.nextInt(10) == 0) {
        patternCount = 0; // empty array
    } else {
        patternCount = 1 + random.nextInt(5); // 1-5 patterns
    }

    String[] patterns = new String[patternCount];
    for (int i = 0; i < patternCount; i++) {
        int choice = random.nextInt(8);
        switch (choice) {
            case 0:
                patterns[i] = "fox"; // known match
                break;
            case 1:
                patterns[i] = "lazy"; // known match
                break;
            case 2:
                patterns[i] = "horse"; // known non-match
                break;
            case 3:
                patterns[i] = ""; // empty pattern
                break;
            case 4:
                patterns[i] = ".*"; // regex special
                break;
            case 5:
                patterns[i] = "\\d+"; // digits regex
                break;
            case 6:
                patterns[i] = "\\s"; // whitespace regex
                break;
            case 7:
                // random short string
                int len = 1 + random.nextInt(5);
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < len; j++) {
                    sb.append((char)('a' + random.nextInt(26)));
                }
                patterns[i] = sb.toString();
                break;
        }
    }

    // Occasionally include null in patterns
    if (random.nextInt(10) == 0 && patterns.length > 0) {
        patterns[random.nextInt(patterns.length)] = null;
    }

    // Occasionally make text null
    if (random.nextInt(20) == 0) {
        text = null;
    }

    return new Object[]{text, patterns};
}

