public static Object[] generateValidInput(Random random) {
    int n;
    int choice = random.nextInt(10);

    if (choice < 3) {
        // Interesting boundary and edge-case values
        int[] specials = {
            0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE,
            9, 10, 99, 100, 999999999
        };
        n = specials[random.nextInt(specials.length)];
    } else if (choice < 7) {
        // Random positive number with 1 to 10 digits
        int digits = random.nextInt(10) + 1;
        if (digits == 1) {
            n = random.nextInt(9) + 1; // 1..9
        } else if (digits == 10) {
            n = 1000000000 + random.nextInt(Integer.MAX_VALUE - 1000000000 + 1);
        } else {
            int min = (int) Math.pow(10, digits - 1);
            int max = (int) Math.pow(10, digits) - 1;
            n = min + random.nextInt(max - min + 1);
        }
    } else if (choice < 9) {
        // Random negative number (not MIN_VALUE, but covers n <= 0 branch)
        n = -random.nextInt(Integer.MAX_VALUE);
    } else {
        // Fully random int, either positive or negative
        n = random.nextInt(Integer.MAX_VALUE);
        if (random.nextBoolean()) {
            n = -n;
        }
    }

    return new Object[]{n};
}

