public static Object[] generateValidInput(Random random) {
    // Randomly decide between normal, boundary, and edge cases
    int caseType = random.nextInt(5);

    if (caseType == 0) {
        // Empty arrays
        return new Object[]{new int[0][0], new int[0]};
    } else if (caseType == 1) {
        // Single element with matching values
        int val = random.nextInt(100) - 50;
        return new Object[]{new int[][]{{val, random.nextInt()}}, new int[]{val}};
    } else if (caseType == 2) {
        // Boundary values with Integer.MAX_VALUE and MIN_VALUE
        int[][] testArray = new int[][]{{Integer.MAX_VALUE, random.nextInt()}, {Integer.MIN_VALUE, random.nextInt()}, {0, random.nextInt()}};
        int[] ordArray = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE, 0};
        return new Object[]{testArray, ordArray};
    } else if (caseType == 3) {
        // Duplicate values in ordArray (as shown in examples)
        int[][] testArray = new int[][]{{random.nextInt(10), random.nextInt()}, {random.nextInt(10), random.nextInt()}, {random.nextInt(10), random.nextInt()}, {random.nextInt(10), random.nextInt()}};
        int[] ordArray = new int[]{testArray[random.nextInt(4)][0], testArray[random.nextInt(4)][0], testArray[random.nextInt(4)][0], testArray[random.nextInt(4)][0]};
        return new Object[]{testArray, ordArray};
    } else {
        // Normal random case with varying sizes
        int n = random.nextInt(10) + 1; // ordArray size 1-10
        int m = random.nextInt(10) + 1; // testArray size 1-10

        int[][] testArray = new int[m][2];
        for (int i = 0; i < m; i++) {
            testArray[i][0] = random.nextInt(20) - 10;
            testArray[i][1] = random.nextInt();
        }

        int[] ordArray = new int[n];
        for (int i = 0; i < n; i++) {
            ordArray[i] = random.nextInt(20) - 10;
        }

        return new Object[]{testArray, ordArray};
    }
}

