        int n = 1;
        int[][] tri = new int[n][];
        tri[0] = new int[1];
        tri[0][0] = random.nextInt(2001) - 1000; // -1000..1000
        return new Object[]{tri, n};
    } else if (choice == 4) {
        // two rows, possibly with edge values
        int n = 2;
        int[][] tri = new int[n][];
        tri[0] = new int[1];
        tri[0][0] = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        tri[1] = new int[2];
        tri[1][0] = random.nextInt(2001) - 1000;
        tri[1][1] = random.nextInt(2001) - 1000;
        return new Object[]{tri, n};
    } else {
        // random n from 3 to 10, mix of values
        int n = 3 + random.nextInt(8); // 3..10
        int[][] tri = new int[n][];
        for (int i = 0; i < n; i++) {
            tri[i] = new int[i + 1];
            for (int j = 0; j <= i; j++) {
                int r = random.nextInt(10);
                int val;
                if (r == 0) val = Integer.MAX_VALUE;
                else if (r == 1) val = Integer.MIN_VALUE;
                else if (r == 2) val = 0;
                else if (r == 3) val = 1;
                else if (r == 4) val = -1;
                else val = random.nextInt(2001) - 1000;
                tri[i][j] = val;
            }
        }
        return new Object[]{tri, n};
    }
}

