public static Object[] generateValidInput(Random random) {
    // Generate random number of rows between 1 and 5
    int rows = 1 + random.nextInt(5);
    // Generate random number of columns between 1 and 5
    int cols = 1 + random.nextInt(5);

    // Create a 2D array with random dimensions
    int[][] array = new int[rows][cols];

    // Fill the array with random integers (including negative, zero, and positive)
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            // Generate values in a wide range to cover various cases
            array[i][j] = random.nextInt(21) - 10; // -10 to 10
        }
    }

    // Randomly choose a column index within the valid range
    int column = random.nextInt(cols);

    // Occasionally return edge cases
    int choice = random.nextInt(10);
    if (choice == 0) {
        // Single row array
        int[][] singleRow = new int[1][cols];
        for (int j = 0; j < cols; j++) {
            singleRow[0][j] = random.nextInt(21) - 10;
        }
        return new Object[]{singleRow, random.nextInt(cols)};
    } else if (choice == 1) {
        // Single column array
        int[][] singleCol = new int[rows][1];
        for (int i = 0; i < rows; i++) {
            singleCol[i][0] = random.nextInt(21) - 10;
        }
        return new Object[]{singleCol, 0};
    } else if (choice == 2) {
        // Array with one element
        return new Object[]{new int[][]{{random.nextInt(21) - 10}}, 0};
    } else if (choice == 3) {
        // Array with all zeros
        int[][] zeros = new int[rows][cols];
        return new Object[]{zeros, random.nextInt(cols)};
    } else if (choice == 4) {
        // Array with all same value
        int sameValue = random.nextInt(21) - 10;
        int[][] sameArray = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sameArray[i][j] = sameValue;
            }
        }
        return new Object[]{sameArray, random.nextInt(cols)};
    } else if (choice == 5) {
        // Array with maximum integer values
        int[][] maxArray = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                maxArray[i][j] = Integer.MAX_VALUE;
            }
        }
        return new Object[]{maxArray, random.nextInt(cols)};
    } else if (choice == 6) {
        // Array with minimum integer values
        int[][] minArray = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                minArray[i][j] = Integer.MIN_VALUE;
            }
        }
        return new Object[]{minArray, random.nextInt(cols)};
    } else if (choice == 7) {
        // Array with mixed extreme values
        int[][] extremeArray = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Alternate between max and min values
                extremeArray[i][j] = (i + j) % 2 == 0 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }
        }
        return new Object[]{extremeArray, random.nextInt(cols)};
    }

    // Default: return the randomly generated array and a random valid column index
    return new Object[]{array, column};
}

