import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class BinomialCoeff {

    /*@ public normal_behavior
      @   requires n >= 0 && k >= 0 && k <= n;
      @   requires n <= 12;
      @   assignable \nothing;
      @   ensures \result == spec_binomial(n, k);
      @*/
    public static int binomialCoeff(int n, int k) {
        if (k > n - k)
            k = n - k;
        int c = 1;
        /*@ maintaining 1 <= i && i <= k + 1;
          @ maintaining c == spec_binomial(n, i - 1);
          @ decreasing k - i + 1;
          @*/
        for (int i = 1; i <= k; i++) {
            c = c * (n - i + 1) / i;
        }
        return c;
    }

    /*@ public normal_behavior
      @   requires n >= 0 && k >= 0 && k <= n;
      @   ensures \result >= 1;
      @   ensures (k == 0 || k == n) ==> \result == 1;
      @   ensures (k > 0 && k < n) ==> \result == spec_binomial(n - 1, k - 1) + spec_binomial(n - 1, k);
      @   measured_by n;
      @ pure
      @*/
    public static int spec_binomial(int n, int k) {
        if (k == 0 || k == n) {
            return 1;
        }
        return spec_binomial(n - 1, k - 1) + spec_binomial(n - 1, k);
    }
}

