public static Object[] generateValidInput(Random random) {
    int[] boundaries = {0, 1, 2, 3, 10, 11, 99, 100, 1001, 120, 1221, Integer.MAX_VALUE, Integer.MAX_VALUE - 1};
    int choice = random.nextInt(boundaries.length + 5);

    if (choice < boundaries.length) {
        return new Object[]{boundaries[choice]};
    }

    // Generate random numbers in various ranges
    switch (choice - boundaries.length) {
        case 0: // small random 0-100
            return new Object[]{random.nextInt(101)};
        case 1: // medium random 100-10000
            return new Object[]{100 + random.nextInt(9901)};
        case 2: // large random 10000-1000000
            return new Object[]{10000 + random.nextInt(990001)};
        case 3: // very large random 1000000-Integer.MAX_VALUE
            return new Object[]{1000000 + random.nextInt(Integer.MAX_VALUE - 1000000)};
        case 4: // random near palindrome numbers
            int base = random.nextInt(1000) + 1;
            String str = String.valueOf(base);
            String reversed = new StringBuilder(str).reverse().toString();
            int pal = Integer.parseInt(str + reversed);
            return new Object[]{pal + random.nextInt(100)};
        default:
            return new Object[]{random.nextInt(Integer.MAX_VALUE)};
    }
}

