public static Object[] generateValidInput(Random random) {
    String input;
    int choice = random.nextInt(14);
    switch (choice) {
        case 0: input = ""; break;
        case 1: input = null; break;
        case 2: input = " "; break;
        case 3: input = "a"; break;
        case 4: input = "\t"; break;
        case 5: input = "   "; break;
        case 6: input = "GoogleFlutter"; break;
        case 7: input = " Google    Flutter "; break;
        case 8: input = "a b\tc\nd"; break;
        case 9: input = " \u00A0 non-breaking space \u00A0 "; break;
        case 10: input = "\u2028 line separator \u2028"; break;
        case 11: input = "   leading and trailing   "; break;
        case 12: input = "\r\n\t mixed \f whitespace \r"; break;
        default:
            int len = random.nextInt(50);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++) {
                int charType = random.nextInt(6);
                if (charType == 0) {
                    sb.append(' ');
                } else if (charType == 1) {
                    sb.append('\t');
                } else if (charType == 2) {
                    sb.append('\n');
                } else if (charType == 3) {
                    sb.append((char) ('a' + random.nextInt(26)));
                } else if (charType == 4) {
                    sb.append((char) ('A' + random.nextInt(26)));
                } else {
                    sb.append((char) ('0' + random.nextInt(10)));
                }
            }
            input = sb.toString();
            break;
    }
    return new Object[]{input};
}

