    public static Object rearrangeBigger(int n) {
        String s = String.valueOf(n);
        char[] c = s.toCharArray();
        int i = 0;
        //@ maintaining 0 <= i && i <= c.length - 1;
        //@ maintaining (\forall int k; 0 <= k && k < i; c[k] >= c[k + 1]);
        while (i < c.length - 1) {
            if (c[i] < c[i + 1]) {
                break;
            }
            i++;
        }
        if (i == c.length - 1) {
            return false;
        }
        int j = c.length - 1;
        //@ maintaining i < j && j <= c.length - 1;
        //@ maintaining (\forall int k; j < k && k < c.length; c[k] <= c[i]);
