class HighestPowerOf2 {

    /*@
      @ requires n >= 1 && n < (1 << 30);   // avoid overflow in power *= 2
      @ ensures \result > 0;
      @ ensures (\result & (\result - 1)) == 0;  // \result is a power of two
      @ ensures \result <= n;
      @ ensures n / 2 < \result;            // equivalent to \result <= n < 2 * \result
      @ assignable \nothing;
      @ pure
      @*/
    public static int highestPowerOf2(int n) {
        int power = 1;

        //@ loop_invariant (power & (power - 1)) == 0 && power >= 1;
        //@ loop_invariant power <= n * 2;    // n*2 is safe because n < 2^30
        //@ decreases Integer.MAX_VALUE - power;
        while (power <= n) {
            power *= 2;
        }
        return power / 2;
    }
}

