            arr1 = new int[n];
            arr2 = new int[m];
            for (int i = 0; i < n; i++) arr1[i] = random.nextInt(20) - 10;
            for (int i = 0; i < m; i++) arr2[i] = random.nextInt(20) - 10;
            break;
        case 2: // Same length, equal sums
            n = random.nextInt(5);
            m = n;
            arr1 = new int[n];
            arr2 = new int[n];
            for (int i = 0; i < n; i++) {
                arr1[i] = random.nextInt(20) - 10;
                arr2[i] = random.nextInt(20) - 10;
            }
            // Adjust last element to make sums equal
            int sum1 = 0, sum2 = 0;
            for (int i = 0; i < n - 1; i++) {
                sum1 += arr1[i];
                sum2 += arr2[i];
            }
            arr2[n - 1] = arr1[n - 1] + (sum1 - sum2);
            break;
        case 3: // Same length, different sums
            n = random.nextInt(5);
            m = n;
            arr1 = new int[n];
            arr2 = new int[n];
            for (int i = 0; i < n; i++) {
                arr1[i] = random.nextInt(20) - 10;
                arr2[i] = random.nextInt(20) - 10;
            }
            if (n > 0) {
                arr2[n - 1] = arr1[n - 1] + 1; // Ensure different sums
            }
            break;
        case 4: // Boundary: empty arrays
            n = 0;
            m = 0;
            arr1 = new int[0];
            arr2 = new int[0];
            break;
        default: // Boundary: null arrays
            n = 0;
            m = 0;
            arr1 = null;
            arr2 = null;
            break;
    }

    return new Object[]{arr1, arr2, n, m};
}

