    switch (choice) {
        case 0:
            // null array
            arr = null;
            n = random.nextInt(21) - 10; // -10 to 10
            break;
        case 1:
            // empty array
            arr = new int[0];
            n = random.nextInt(21) - 10;
            break;
        case 2:
            // random array (possibly with duplicates)
            int len = random.nextInt(5) + 1; // 1-5
            arr = new int[len];
            for (int idx = 0; idx < len; idx++) {
                arr[idx] = random.nextInt(6); // values 0-5
            }
            n = random.nextInt(21) - 10;
            break;
        case 3:
            // array with duplicates that satisfy the second loop condition
            // choose a duplicate value i (0-5) and repetition count k (2-4)
            int dupValue = random.nextInt(6);
            int repeatCount = random.nextInt(3) + 2; // 2-4
            int factor = random.nextInt(4); // 0-3
            n = dupValue + factor * repeatCount; // guarantees (n - dupValue) % repeatCount == 0

            // create array with repeatCount copies of dupValue and some extra distinct elements
            int extra = random.nextInt(3); // 0-2 extra elements
            int totalLen = repeatCount + extra;
            arr = new int[totalLen];
            for (int j = 0; j < repeatCount; j++) {
                arr[j] = dupValue;
            }
            // fill extra positions with values different from dupValue
            for (int j = repeatCount; j < totalLen; j++) {
                int val = random.nextInt(6);
                while (val == dupValue) {
                    val = random.nextInt(6);
                }
                arr[j] = val;
            }
            break;
        default:
            // Should not reach here, but keeps compiler happy
            arr = new int[0];
            n = 0;
            break;
    }

    // with 20% probability, set n to a boundary value
    if (random.nextDouble() < 0.2) {
        int[] boundaries = {Integer.MIN_VALUE, Integer.MAX_VALUE, 0, 1, -1};
        n = boundaries[random.nextInt(boundaries.length)];
    }

    return new Object[]{arr, Integer.valueOf(n)};
}

