import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class FindKProduct {

    /*@ public normal_behavior
      @   requires testArray != null;
      @   requires k >= 0;
      @   requires (\forall int i; 0 <= i && i < testArray.length; 
      @               testArray[i] != null && k < testArray[i].length);
      @   assignable \nothing;
      @   ensures \result == productAtK(testArray, k, testArray.length);
      @*/
    public static int findKProduct(int[][] testArray, int k) {
        int product = 1;
        int n = testArray.length;
        /*@ maintaining 0 <= i && i <= n;
          @ maintaining product == productAtK(testArray, k, i);
          @ decreasing n - i;
          @*/
        for (int i = 0; i < n; i++) {
            product *= testArray[i][k];
        }
