public static Object[] generateValidInput(Random random) {
    // Decide input type: 0 = normal, 1 = empty outer, 2 = null outer, 3 = null inner, 4 = inner too short
    int choice = random.nextInt(5);
    Object[][] testList;

    switch (choice) {
        case 0: // normal random input
            int outerLen = random.nextInt(5) + 1; // 1 to 5
            testList = new Object[outerLen][];
            for (int i = 0; i < outerLen; i++) {
                int innerLen = random.nextInt(3) + 3; // 3 to 5, ensure at least 3
                testList[i] = new Object[innerLen];
                // fill with random objects, but third element must be Integer
                for (int j = 0; j < innerLen; j++) {
                    if (j == 2) {
                        // generate boundary Integer values
                        int intChoice = random.nextInt(5);
                        switch (intChoice) {
                            case 0: testList[i][j] = 0; break;
                            case 1: testList[i][j] = Integer.MAX_VALUE; break;
                            case 2: testList[i][j] = Integer.MIN_VALUE; break;
                            case 3: testList[i][j] = -1; break;
                            default: testList[i][j] = random.nextInt(200) - 100; break;
                        }
                    } else {
                        // other elements can be any object (String, Integer, etc.)
                        int elemChoice = random.nextInt(3);
                        switch (elemChoice) {
                            case 0: testList[i][j] = random.nextInt(); break;
                            case 1: testList[i][j] = "test" + random.nextInt(100); break;
                            default: testList[i][j] = null; break;
                        }
                    }
                }
            }
            break;
        case 1: // empty outer array
            testList = new Object[0][];
            break;
        case 2: // null outer array
            testList = null;
            break;
        case 3: // one inner array is null
            outerLen = random.nextInt(3) + 2; // 2 to 4
            testList = new Object[outerLen][];
            for (int i = 0; i < outerLen; i++) {
                if (i == outerLen - 1) {
                    testList[i] = null; // null inner array
                } else {
                    int innerLen = random.nextInt(2) + 3; // 3 or 4
                    testList[i] = new Object[innerLen];
                    for (int j = 0; j < innerLen; j++) {
                        if (j == 2) {
                            testList[i][j] = random.nextInt(200) - 100;
                        } else {
                            testList[i][j] = random.nextInt();
                        }
                    }
                }
            }
            break;
        case 4: // inner array with less than 3 elements (index 2 out of bounds)
            outerLen = random.nextInt(3) + 1; // 1 to 3
            testList = new Object[outerLen][];
            for (int i = 0; i < outerLen; i++) {
                int innerLen = random.nextInt(2) + 1; // 1 or 2 (less than 3)
                testList[i] = new Object[innerLen];
                for (int j = 0; j < innerLen; j++) {
                    testList[i][j] = random.nextInt();
                }
            }
            break;
        default:
            // fallback, should not happen
            testList = new Object[][]{{1, "a", 2}};
    }

    return new Object[]{testList};
}

