public static Object[] generateValidInput(Random random) {
    // Decide whether to return null for the string (10% chance)
    if (random.nextDouble() < 0.1) {
        // Generate a random k from -5 to 14
        int k = random.nextInt(20) - 5;
        return new Object[] { null, k };
    }

    // Generate a random string with words separated by spaces
    int numWords = random.nextInt(10); // 0 to 9 words
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < numWords; i++) {
        // Word length: 0 to 5 (including empty words)
        int wordLen = random.nextInt(6);
        for (int j = 0; j < wordLen; j++) {
            sb.append((char) ('a' + random.nextInt(26)));
        }
        // Add spaces between words (1 to 3 spaces)
        if (i < numWords - 1) {
            int spaces = 1 + random.nextInt(3);
            for (int s = 0; s < spaces; s++) {
                sb.append(' ');
            }
        }
    }

    // Occasionally add leading/trailing spaces
    if (random.nextBoolean()) {
        sb.insert(0, ' ');
    }
    if (random.nextBoolean()) {
        sb.append(' ');
    }

    String testStr = sb.toString(); // Keep as generated (may have multiple spaces, leading/trailing)

    // Choose a diverse k value
    int k;
    int choice = random.nextInt(10);
    switch (choice) {
        case 0: k = -1; break;
        case 1: k = 0; break;
        case 2: k = 1; break;
        case 3: k = 2; break;
        case 4: k = 3; break;
        case 5: k = 5; break;
        case 6: k = 10; break;
        case 7: k = Integer.MAX_VALUE; break;
        case 8: k = Integer.MIN_VALUE; break;
        default: k = random.nextInt(10); // 0-9
    }

    return new Object[] { testStr, k };
}

