            tuple = new Object[]{randomString(random, 5), randomString(random, 5), randomString(random, 5)};
            index = -1;
            break;
        case 4:
            // Boundary: index = length - 1 (last element)
            tuple = new Object[]{randomString(random, 5), randomString(random, 5), randomString(random, 5), randomString(random, 5)};
            index = tuple.length - 1;
            break;
        case 5:
            // Boundary: index = -length (first element)
            tuple = new Object[]{randomString(random, 5), randomString(random, 5), randomString(random, 5)};
            index = -tuple.length;
            break;
        case 6:
