            tuple = new Object[random.nextInt(10) + 1];
            for (int i = 0; i < tuple.length; i++) {
                tuple[i] = randomString(random, 5);
            }
            index = random.nextInt(tuple.length);
            break;
        case 9:
            // Larger tuple with random negative index within bounds
            tuple = new Object[random.nextInt(10) + 1];
            for (int i = 0; i < tuple.length; i++) {
