public static Object[] generateValidInput(Random random) {
    // Decide which scenario to generate
    int scenario = random.nextInt(10);

    String text;
    String pattern;

    switch (scenario) {
        case 0: // Normal case: pattern found at a random position
            {
                int textLen = random.nextInt(20) + 5; // 5..24
                int patLen = random.nextInt(5) + 1; // 1..5
                int pos = random.nextInt(textLen - patLen + 1);
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < textLen; i++) {
                    if (i >= pos && i < pos + patLen) {
                        // insert pattern character
                        char c = (char) (random.nextInt(26) + 'a');
                        sb.append(c);
                    } else {
                        sb.append((char) (random.nextInt(26) + 'a'));
                    }
                }
                text = sb.toString();
                pattern = text.substring(pos, pos + patLen);
                break;
            }
        case 1: // Pattern not found
            {
                int textLen = random.nextInt(20) + 5;
                int patLen = random.nextInt(5) + 1;
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < textLen; i++) {
                    sb.append((char) (random.nextInt(26) + 'a'));
                }
                text = sb.toString();
                // Generate a pattern that is guaranteed not to appear
                StringBuilder patSb = new StringBuilder();
                for (int i = 0; i < patLen; i++) {
                    patSb.append((char) (random.nextInt(26) + 'a'));
                }
                pattern = patSb.toString();
                // Ensure pattern is not equal to any substring of text
                // Simple: just generate a random pattern, it might accidentally match, but low probability.
                // To be safe, we could check, but for simplicity we accept low chance.
                break;
            }
        case 2: // Empty text
            text = "";
            pattern = random.nextBoolean() ? "" : randomString(random, 1, 5);
            break;
        case 3: // Empty pattern
            text = randomString(random, 1, 10);
            pattern = "";
            break;
        case 4: // Pattern equals text
            {
                int len = random.nextInt(10) + 1;
                String s = randomString(random, len, len);
                text = s;
                pattern = s;
                break;
            }
        case 5: // Pattern longer than text
            text = randomString(random, 1, 5);
            pattern = randomString(random, 6, 10);
            break;
        case 6: // Pattern at start
            {
                int patLen = random.nextInt(5) + 1;
                String pat = randomString(random, patLen, patLen);
                int suffixLen = random.nextInt(10) + 1;
                text = pat + randomString(random, suffixLen, suffixLen);
                pattern = pat;
                break;
            }
        case 7: // Pattern at end
            {
                int patLen = random.nextInt(5) + 1;
                String pat = randomString(random, patLen, patLen);
                int prefixLen = random.nextInt(10) + 1;
                text = randomString(random, prefixLen, prefixLen) + pat;
                pattern = pat;
                break;
            }
        case 8: // Multiple occurrences, ensures first is returned
            {
                String pat = randomString(random, 2, 4);
                int part1 = random.nextInt(5) + 1;
                int part2 = random.nextInt(5) + 1;
                text = pat + randomString(random, part1, part1) + pat + randomString(random, part2, part2);
                pattern = pat;
                break;
            }
        case 9: // Null inputs
            {
                if (random.nextBoolean()) {
                    text = null;
                    pattern = randomString(random, 1, 5);
                } else {
                    text = randomString(random, 1, 5);
                    pattern = null;
                }
                break;
            }
        default:
            // fallback
            text = "hello";
            pattern = "ll";
            break;
    }

    return new Object[]{text, pattern};
}

// Helper method to generate a random string of given length range
private static String randomString(Random random, int minLen, int maxLen) {
