import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class FindNthDigit {

    /*@ public normal_behavior
      @   requires n > 0;
      @   requires q > 0;
      @   requires p >= 0;
      @   requires p < q;
      @   requires n <= 9;
      @   ensures \result >= 0 && \result <= 9;
      @   assignable \nothing;
      @*/
    public static int findNthDigit(int p, int q, int n) {
        int res = 0;
        /*@ loop_invariant n >= 0;
          @ loop_invariant p >= 0 && p < q;
          @ loop_invariant res >= 0 && res <= 9;
          @ decreases n;
          @*/
        while (n > 0) {
            n -= 1;
            p *= 10;
            res = p / q;
            p %= q;
        }
        return res;
    }
}

