        "multiple   spaces",    // extra spaces between words
        "verylongword",         // single very long word
        null                    // null input
    };

    // About 50% chance to pick a predefined case, otherwise generate random
    if (random.nextBoolean()) {
        String text = predefinedCases[random.nextInt(predefinedCases.length)];
        return new Object[]{text};
    } else {
        // Generate random string with random words
        int wordCount = random.nextInt(10); // 0 to 9 words
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < wordCount; i++) {
            if (i > 0) sb.append(" ");
            // Determine word length: either short (1-3) or long (4-8)
            boolean longWord = random.nextBoolean();
            int wordLen = longWord ? random.nextInt(5) + 4 : random.nextInt(3) + 1;
            for (int j = 0; j < wordLen; j++) {
                // Generate random lowercase letter
                char c = (char) ('a' + random.nextInt(26));
                sb.append(c);
            }
        }
        String text = sb.toString();
        return new Object[]{text};
    }
}

