import java.math.*;

class CountTuplex {

    /*@ requires a != null && 0 <= lo && lo <= hi && hi <= a.length;
      @ ensures (lo >= hi) ==> \result == 0;
      @ ensures (lo < hi) ==> \result == ((a[hi-1] == value) ? 1 : 0) + countRange(a, value, lo, hi-1);
      @ assignable \nothing;
      @ pure
      @*/
    public static int countRange(int[] a, int value, int lo, int hi) {
        if (lo >= hi) {
            return 0;
        } else {
            return (a[hi-1] == value ? 1 : 0) + countRange(a, value, lo, hi-1);
        }
    }

    /*@ requires tuplex != null;
      @ ensures \result == countRange(tuplex, value, 0, tuplex.length);
      @ assignable \nothing;
      @ pure
      @*/
    public static int countTuplex(int[] tuplex, int value) {
        int count = 0;
        //@ loop_invariant 0 <= i && i <= tuplex.length;
        //@ loop_invariant count == countRange(tuplex, value, 0, i);
        //@ decreases tuplex.length - i;
        for (int i = 0; i < tuplex.length; i++) {
            if (tuplex[i] == value) {
                count++;
            }
        }
        return count;
    }
}

