// Helper method to generate random string
private static String generateRandomString(Random random, int length) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        int choice = random.nextInt(3);
        if (choice == 0) {
            sb.append((char)('a' + random.nextInt(26)));  // lowercase letter
        } else if (choice == 1) {
            sb.append((char)('A' + random.nextInt(26)));  // uppercase letter
        } else {
            sb.append((char)('0' + random.nextInt(10)));  // digit
        }
    }
    return sb.toString();
}

// Helper method to generate random string with spaces
private static String generateRandomStringWithSpaces(Random random, int length) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
        int choice = random.nextInt(4);
        if (choice == 0) {
            sb.append(' ');  // space
        } else if (choice == 1) {
            sb.append((char)('a' + random.nextInt(26)));  // lowercase letter
        } else if (choice == 2) {
            sb.append((char)('A' + random.nextInt(26)));  // uppercase letter
        } else {
            sb.append((char)('0' + random.nextInt(10)));  // digit
        }
    }
    return sb.toString();
}

