            int diff = random.nextInt(5) + 1;
            int len = random.nextInt(5) + 2;
            seqNums = new int[len];
            for (int i = 0; i < len; i++) {
                seqNums[i] = start + i * diff;
            }
            break;
        case 4:
            // Linear sequence with negative difference
            start = random.nextInt(21) - 10;
            diff = -(random.nextInt(5) + 1);
            len = random.nextInt(5) + 2;
            seqNums = new int[len];
            for (int i = 0; i < len; i++) {
                seqNums[i] = start + i * diff;
            }
            break;
        case 5:
            // Non-linear sequence with a break
            len = random.nextInt(4) + 3; // at least 3 elements
            seqNums = new int[len];
            int base = random.nextInt(21) - 10;
