        case 4: // list with duplicates (same reference) including boundaries
            list = new ArrayList<>();
            // add some base values
            int baseSize = 3 + random.nextInt(3);
            for (int i = 0; i < baseSize; i++) {
                list.add(randomBoundaryInt(random));
            }
            // duplicate one of them by adding the same reference
            int dupIndex = random.nextInt(list.size());
            list.add(list.get(dupIndex));
            // possibly add another duplicate of a different element
