            testTup.add(random.nextInt(200) - 100);
            n = random.nextInt(3) + 1; // 1..3
            break;
        case 3: // list size equals n
            n = random.nextInt(5) + 1; // 1..5
            testTup = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            break;
        case 4: // list size multiple of n (2*n)
            n = random.nextInt(3) + 1; // 1..3
            int size = 2 * n;
            testTup = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            break;
        case 5: // n = 1 (edge case)
            testTup = new ArrayList<>();
            int len = random.nextInt(5) + 1;
            for (int i = 0; i < len; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            n = 1;
            break;
        case 6: // n larger than list size
            testTup = new ArrayList<>();
            len = random.nextInt(5) + 1;
            for (int i = 0; i < len; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            n = len + random.nextInt(5) + 1; // n > len
            break;
        case 7: // list with many elements
            testTup = new ArrayList<>();
            int listSize = random.nextInt(10) + 5; // 5..14
            for (int i = 0; i < listSize; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            n = random.nextInt(5) + 1; // 1..5
            break;
        case 8: // n = 2 (edge case)
            testTup = new ArrayList<>();
            len = random.nextInt(5) + 1;
            for (int i = 0; i < len; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            n = 2;
            break;
        default: // random normal case
            testTup = new ArrayList<>();
            int size2 = random.nextInt(10);
            for (int i = 0; i < size2; i++) {
                testTup.add(random.nextInt(200) - 100);
            }
            n = random.nextInt(5) + 1; // 1..5
            break;
    }

    return new Object[]{testTup, n};
