class FloorMin {

    /*@
      @ requires b > 0;
      @ requires a >= 0;
      @ requires n >= 0;
      @ requires (long) a * (b - 1) <= Integer.MAX_VALUE;
      @ requires (long) a * n <= Integer.MAX_VALUE;
      @ assignable \nothing;
      @ ensures (b - 1 >= n) ==> \result == (a * (b - 1)) / b;
      @ ensures (b - 1 < n)  ==> \result == (a * n) / b;
      @ ensures \result >= 0;
      @ pure
      @*/
    public static int floorMin(int a, int b, int n) {
        int x = Math.max(b - 1, n);
        return (a * x) / b;
    }
}

