        "Hello, world! Hello, world!",
        "patternpatternpattern",
        "x" // single character
    };

    String[] patterns = {
        "a",
        "fox",
        "crazy",
        "will",
        "aa", // pattern within repeated characters
        "abc", // pattern repeated
        "Hello",
        "pattern",
        "x",
        "z" // pattern not present
    };

    // Select random text and pattern, with some bias toward boundary cases
    String text;
    String pattern;

    int choice = random.nextInt(10);
    if (choice < 2) {
        // Boundary cases: empty text or short text
        text = texts[random.nextInt(2)]; // "" or "a"
        pattern = patterns[random.nextInt(patterns.length)];
    } else if (choice < 4) {
        // Specific examples from description
        text = texts[2 + random.nextInt(3)]; // one of the three example texts
        pattern = patterns[1 + random.nextInt(3)]; // one of the three example patterns
    } else if (choice < 6) {
        // Repeated characters / patterns
        text = texts[5 + random.nextInt(2)]; // "aaaa" or "abcabcabc"
        pattern = patterns[4 + random.nextInt(2)]; // "aa" or "abc"
    } else if (choice < 8) {
        // Random normal case
        text = texts[random.nextInt(texts.length)];
        pattern = patterns[random.nextInt(patterns.length)];
    } else {
        // Random text with random pattern (may or may not be present)
        text = texts[random.nextInt(texts.length)];
        pattern = patterns[random.nextInt(patterns.length)];
        // Sometimes make pattern a substring of text
        if (random.nextBoolean() && text.length() > 0) {
            int start = random.nextInt(text.length());
            int len = random.nextInt(text.length() - start) + 1;
            pattern = text.substring(start, start + len);
        }
    }

    // Avoid null for text and pattern to prevent potential issues
    // But occasionally test null for robustness
    if (random.nextInt(20) == 0) {
        if (random.nextBoolean()) {
            text = null;
        } else {
            pattern = null;
        }
    }

    return new Object[]{text, pattern};
}

