class StringLiterals {

    /*@ public normal_behavior
      @   requires patterns != null && text != null;
      @   requires (\forall int i; 0 <= i && i < patterns.length; patterns[i] != null);
      @   ensures \result != null;
      @   ensures \result.equals("Matched!") <==> 
      @           (\exists int i; 0 <= i && i < patterns.length; text.contains(patterns[i]));
      @   ensures \result.equals("Not Matched!") <==> 
      @           (\forall int i; 0 <= i && i < patterns.length; !text.contains(patterns[i]));
      @   ensures \result.equals("Matched!") || \result.equals("Not Matched!");
