import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class CombSort {

    /*@ requires nums != null;
      @ ensures \result == nums;
      @ ensures (\forall int i; 0 <= i && i < nums.length - 1; nums[i] <= nums[i + 1]);
      @ ensures (\forall int i; 0 <= i && i < nums.length;
      @           (\num_of int j; 0 <= j && j < nums.length; nums[j] == \old(nums[i]))
      @           ==
      @           (\num_of int j; 0 <= j && j < nums.length; \old(nums[j]) == \old(nums[i])));
      @ assignable nums[*];
      @*/
    public static int[] combSort(int[] nums) {
        int n = nums.length;
        int gap = n;
        boolean swapped = true;

        //@ loop_invariant gap >= 0;
        //@ loop_invariant (\forall int i; 0 <= i && i < nums.length - 1; nums[i] <= nums[i + 1]) ==> (gap <= 1 && !swapped);
        //@ loop_decreases gap;
        while (gap > 1 || swapped) {
            gap = (int) (gap / 1.3);
            swapped = false;

            //@ loop_invariant 0 <= i && i + gap <= n;
            //@ loop_invariant (\forall int k; 0 <= k && k < i; nums[k] <= nums[k + gap]);
            //@ loop_decreases n - i;
            for (int i = 0; i + gap < n; i++) {
                if (nums[i] > nums[i + gap]) {
                    int temp = nums[i];
                    nums[i] = nums[i + gap];
                    nums[i + gap] = temp;
                    swapped = true;
                }
            }
        }
        return nums;
    }
}

