public static Object[] generateValidInput(Random random) {
    int n;
    int[] arr;

    // Choose a random case type
    int caseType = random.nextInt(5);

    switch (caseType) {
        case 0:
            // Small normal case
            n = 1 + random.nextInt(5) * 2; // odd length 1,3,5,7,9
            arr = new int[n];
            // Fill with pairs and one single element at random position
            int singlePos = random.nextInt(n);
            int val = 1;
            for (int i = 0; i < n; i += 2) {
                if (i == singlePos) {
                    arr[i] = val;
                    val++;
                    i--;
                } else if (i + 1 < n) {
                    arr[i] = val;
                    arr[i + 1] = val;
                    val++;
                } else {
                    arr[i] = val;
                }
            }
            break;
        case 1:
            // Boundary: single element at beginning
            n = 1 + random.nextInt(5) * 2;
            arr = new int[n];
            arr[0] = 0;
            int val1 = 1;
            for (int i = 1; i < n; i += 2) {
                arr[i] = val1;
                arr[i + 1] = val1;
                val1++;
            }
            break;
        case 2:
            // Boundary: single element at end
            n = 1 + random.nextInt(5) * 2;
            arr = new int[n];
            int val2 = 0;
            for (int i = 0; i < n - 1; i += 2) {
                arr[i] = val2;
                arr[i + 1] = val2;
                val2++;
            }
            arr[n - 1] = val2;
            break;
        case 3:
            // Edge: single element only
            n = 1;
            arr = new int[]{random.nextInt(100)};
            break;
        case 4:
            // Edge: large values and large array
            n = 1 + random.nextInt(10) * 2; // up to 21
            arr = new int[n];
            int singlePos2 = random.nextInt(n);
            int val3 = random.nextInt(1000000);
            for (int i = 0; i < n; i += 2) {
                if (i == singlePos2) {
                    arr[i] = val3;
                    val3 += 1000000;
                    i--;
                } else if (i + 1 < n) {
                    arr[i] = val3;
                    arr[i + 1] = val3;
                    val3 += 1000000;
                } else {
                    arr[i] = val3;
                }
            }
            break;
        default:
            n = 1;
            arr = new int[]{0};
    }

    return new Object[]{arr, n};
}

