public static Object[] generateValidInput(Random random) {
    // Decide array type: null, empty, or with elements
    int arrayChoice = random.nextInt(4);
    String[] testArray;
    switch (arrayChoice) {
        case 0:
            testArray = null;
            break;
        case 1:
            testArray = new String[0];
            break;
        case 2:
            // Array with one element
            testArray = new String[]{randomString(random, 0, 5)};
            break;
        default:
            // Array with random length (2 to 5)
            int len = random.nextInt(4) + 2; // 2..5
            testArray = new String[len];
            for (int i = 0; i < len; i++) {
                testArray[i] = randomString(random, 0, 8);
            }
            break;
    }

    // Decide testStr: null, empty, or random
    int strChoice = random.nextInt(3);
    String testStr;
    switch (strChoice) {
        case 0:
            testStr = null;
            break;
        case 1:
            testStr = "";
            break;
        default:
            testStr = randomString(random, 1, 10);
            break;
    }

    return new Object[]{testArray, testStr};
}

// Helper method to generate a random string of length between minLen and maxLen
private static String randomString(Random random, int minLen, int maxLen) {
    int len = minLen + (maxLen > minLen ? random.nextInt(maxLen - minLen + 1) : 0);
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        // Generate printable ASCII characters (32-126)
        char c = (char) (random.nextInt(95) + 32);
        sb.append(c);
    }
    return sb.toString();
}

