import java.math.*;


class LastDigitFactorial {

    /*@ requires n >= 0 && n <= 12;
      @ ensures (n >= 4 ==> \result == n % 10) && (n < 4 ==> \result == 0);
      @ assignable \nothing;
      @*/
    public static int lastDigitFactorial(int n) {
        int lastDigit = 0;
        int factorial = 1;
        /*@ maintaining 0 <= i && i <= n;
          @ maintaining factorial == (\product int j; i + 1 <= j && j <= n; j);
          @ decreasing i;
          @*/
        for(int i = n; i >= 1; i--) {
            factorial = factorial * i;
        }
        //@ assert factorial == (\product int j; 1 <= j && j <= n; j);
        int lastDigitInFactorial = (int) Math.log10(factorial);
        //@ assume (lastDigitInFactorial > 0) == (n >= 4);
        if(lastDigitInFactorial > 0) {
            lastDigit = n % 10;
        }
        return lastDigit;
    }
}

