public static Object[] generateValidInput(Random random) {
    // Decide list size: 0 to 5
    int listSize = random.nextInt(6);
    java.util.List<String> testList = new java.util.ArrayList<>();
    for (int i = 0; i < listSize; i++) {
        // Decide number of tokens in this string (1 to 4)
        int tokenCount = random.nextInt(4) + 1;
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < tokenCount; j++) {
            boolean isNumber = random.nextBoolean();
            if (isNumber) {
                // Generate a non-negative integer
                int num;
                if (random.nextDouble() < 0.1) {
                    // Large number
                    num = random.nextInt(Integer.MAX_VALUE / 2) + 1;
                } else {
                    num = random.nextInt(1000);
                }
                sb.append(num);
            } else {
                // Generate a random word (lowercase letters)
                int wordLen = random.nextInt(6) + 1; // 1 to 6
                for (int k = 0; k < wordLen; k++) {
                    char c = (char) (random.nextInt(26) + 'a');
                    sb.append(c);
                }
            }
            if (j < tokenCount - 1) {
                sb.append(' ');
            }
        }
        testList.add(sb.toString());
    }

    // Generate k
    int k;
    double prob = random.nextDouble();
    if (prob < 0.15) {
        k = 0;
    } else if (prob < 0.30) {
        k = 1;
    } else if (prob < 0.45) {
        k = -1;
    } else if (prob < 0.55) {
        k = Integer.MAX_VALUE;
    } else if (prob < 0.65) {
        k = Integer.MIN_VALUE;
    } else {
        k = random.nextInt(2001) - 1000; // range -1000 to 1000
    }

    return new Object[]{testList, k};
}

